INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون العمل الموحد رقم12لسنة2003', 'المادة 248', 'يعاقب صاحب العمل أو من يمثله عن المنشأة الذى يخالف أيًا من أحكام المواد ٧٣ (فقرة ثانية)، ٧٤، ٧٥، ٨٩، ٩٠، ٩٨، ٩٩، ١٠٠، ١٠١، ١٠٢ من هذا القانون والقرارات الوزارية المنفذة لها بغرامة لا تقل عن خمسمائة جنيه ولا تجاوز ألف جنيه، وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة وتضاعف الغرامة فى حالة العود.
وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة وتضاعف الغرامة فى حالة العود.(١)', 'flashsa-lawyers');
