INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون المرافعات', 'المادة 33', '---- 
إذا رفعت لمحاكم الجمهورية دعوى داخلة فى اختصاصها تكون هذه المحاكم مختصة بالفصل فى المسائل الأولية و الطلبات العارضة على الدعوى الأصلية كما تختص بالفصل فى كل طلب يرتبط بهذه الدعوى و يقتضى حسن سير العدالة أن ينظر معها .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون المرافعات', 'المادة 34', '----- 
