INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 54', 'يصدر بتعيين العسكريين قرار من وزير الحربية بناءً علي اقتراح مدير القضاة العسكري.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 55', 'يعين القضاة العسكريون من ضباط القوات المسلحة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 56', 'يحلف القضاة العسكريون وأعضاء النيابة العسكرية قبل مباشرة وظائفهم اليمين التالية: ( أقسم بالله العظيم أن لحكم بالعدل وأحترم القانون)

ويؤدي اليمين أمام نائب القائد الأعلى للقوات المسلحة وبحضور مدير القضاة العسكريون.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 57', 'يخضع القضاة العسكريون لكافة الأنظمة المنصوص عليها في القوانين العسكرية.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 58', 'يعتبر ضباط القضاء العسكري نظراء للقضاة المدنيين .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 59', 'يكون تعيين القضاة العسكريون لمدة سنتين قابلة للتجديد ولا يجوز نقلهم إلي مناصب أخري إلا للضرورات العسكرية.

الفصل الرابع 
صلاحية الأعضاء والمعارضة', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 60', 'يمتنع علي رئيس أو عضو المحكمة أن يشترك في نظر دعمي إذا تحقق فيه سبب من الأسباب الآتية :
1-أن تكون الجريمة قد وقعت عليه شخصياً .
2- أن يكون قد قام فيها بعمل من أعمال التحقيق أو الإحالة .
3-أن تكون له ولزوجته أو لأحد أقاربه أو أصهاره إلي الدرجة الرابعة مصلحة في الدعوى.
4- أن يكون شاهداً أو أدي عملاً من أعمال الخبرة فيها.
5-إذا كان قريباً أو صهراً لأحد المتهمين إلي الدرجة الرابعة.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 61', 'تجوز المعارضة في عضو أو رئيس المحكمة العسكرية كما يجوز له من تلقاء نفسه التنحي عن نظر الدعوى إذا توافرت فيه أحد الأسباب الواردة في المادة السابقة.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 62', 'يجب تقديم طلب المعارضة قبل تقديم أي دفع أو دفاع وإلا سقط الحق فيه ، وتثبت إجراءات المعارضة في محضر الجلسة.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 63', 'إذا ظهر للمحكمة أن المعارضة جدية تصدر قراراً بقبولها وترفع الأمر إلي الضابط الآمر بالإحالة.

