INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 64', 'تنقضي الدعوى العسكرية في مواد الجنايات بمضي عشر سنين من يوم وقوع الجريمة ، وفي مواد الجنح بمضي ثلاث سنين ، وفي مواد المخالفات بمضي سنة ما لم ينص القانون علي خلاف ذلك .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 65', 'لا تنقضي الدعوى في جرائم الهروب والفتنة.

