INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 79', 'يبدا الرئيس في اخذ الأصوات علي الحكم مبتدئا بأحدث الأعضاء وتصدر الأحكام بأغلبية الاراء0', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 80', 'يصدر الحكم بالإعدام بإجماع الآراء 0', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 81', 'يصدر الحكم في جلسة علنية ولو كانت المحاكمة سريه ويوقع عليه رئيس وأعضاء المحكمة قبل النطق به ويثبت في محضر الجلسة فيما عدا جزاء السجن فأكثر يكون صدور الحكم بعد التصديق عليه بالنسبة للضابط0

وللمحكمة أن تأمر بأخذ الوسائل اللازمة لمنع المتهم من مغادرة قاعة الجلسة قبل النطق بالحكم او لضمان حضوره في الجلسة التي يؤجل إليها الحكم ولو كان ذلك بإصدار أمر بحبسه إذا كانت الواقعة مما يجوز غيها الحبس الإحتياطي0', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 82', 'يشمل الحكم علي الأسباب التي بني عليها ،وكل حكم يجب أن يشتمل علي بيان الواقعة والظروف التي وقعت فيها والرد علي كل طلب هام ، او دفع جوهري وان يشير إلي نص القانون الذي حكم بموجبه 0', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 83', 'إذا رغبت المحكمة في تقديم أية ملاحظات مرتبطة بالدعوى ظهرت لها أثناء نظرها جاز لها ان تكتب عنه مذكرة منفصلة ترفع مع الإجراءات إلي الضابط المصدق0', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 84', 'لا تصبح الأحكام نهائية إلا بعد التصديق عليها علي الوجه المبين في هذا القانون0

