INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 88', 'إذا لم توجد النيابة العسكرية أثناء الخدمة في الميدان يباشر اختصاصاتها ويكون لهم جميع سلطاتها 0
ويجوز للقائد ان يكلف أحد الضباط التابعين له بأعمال النيابة العسكرية في حدود منطقة اختصاصه0', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 89', 'للقائد أثناء الخدمة في الميدان سلطة إصدار الأمر بحبس المتهم احتياطيا ويراعي قائد القوات في الميدان بأوامر الحبس الاحتياطي الصادر علي الضابط ويكون الإفراج عنهم بأمر من قائد القوات في الميدان او من ينوب عنه0', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 90', 'للقادة حق التصرف في التحقيقات التي تقع في دائرة اختصاصاتهم بالحفظ او بتوقيع جزاء انضباطي او بالإحالة إلي محاكم الميدان او المحاكم العسكرية العادية0', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 91', 'يجوز عند الضرورة إحالة المتهم إلي محكمة الميدان مباشرة دون تحقيق بناء علي مذكرة من القائد المختص وذلك بعد اخذ اقواله0

