INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 94', 'يمثل النيابة العسكرية أمام محاكم الميدان أي ضابط يعين لذلك بأمر االمختص0', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون التحكيم', 'المادة 95', 'يحلف رئيس وأعضاء المحكمة قبل بدء المحاكم اليمين التالية :
