INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 1', 'لا يقع طلاق السكران والمكره.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 2', 'لا يقع الطلاق غير المنجز إذا قصد به الحمل على فعل شئ او تركة لا غير.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 3', 'الطلاق المقترن بعدد لفظا أو إشارة لا يقع واحدة.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 4', 'كنايات الطلاق وهى ما تحتمل الطلاق وغيره ولا يقع بها الطلاق إلا بالنية.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 5', 'كل طلاق يقع رجعيا الا المكمل للثلاث والطلاق قبل الدخول والطلاق على مال وما نص على كونه بائنا فى هذا القانون والقانون رقم 25 لسنة 1920.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 5', 'مكررا
على المطلق أن يوثق إشهاد طلاقه لدى الموثق المختص خلال ثلاثين يوما من إيقاع الطلاق.
وتعتبر الزوجة عالمة بالطلاق بحضورها توثيقه. فإذا لم تحضره كان على الموثق إعلان الطلاق لشخصها على يد محضر, وعلى الموثق تسليم نسخة إشهاد الطلاق للمطلقة او من ينوب عنها, وفق الإجراءات التي يصدر بها قرار من وزير العدل.
وترتب أثار الطلاق من تاريخ إيقاعه إلا إذا أخفاه الزوج عن الزوجة , فلا تترتب أثاره من حيث الميراث والحقوق المالية الأخرى إلا من تاريخ علمها به.

الشقاق
الشقاق بين الزوجين والتطليق للضرر', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 6', 'اذا ادعت الزوجة إضرار الزوج بها بما لا يستطاع معه دوام العشرة بين أمثالها يجوز لها ان تطلب من القاضى التفريق وحينئذ يطلقها القاضى طلقة بائنة إذا ثبت الضرر وعجز عن الإصلاح بينها فإذا رفض الطلب ثم تكررت الشكوى ولم يثبت الضرر بعث القاضى حكمين وقضى على الوجه المبين بالمواد 11,10,9,8,7.

الحكمين وإجراءات عملهم', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 7', 'يشترط فى الحكمين ان يكونا عدلين من أهل الزوجين إن أمكن وإلا فمن غيرهم ممن لهم خبرة بحالها وقدرة على الإصلاح بينهما.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 8', 'يشتمل قرار بعث الحكمين على تاريخ بدء وانتهاء ماموريتهما على الا تجاوز مدة ستة اشهر وتخطر المحكمة الحكمين والخصم بذلك وعليها تحليف كل من الحكمين اليمين ان يقوم بمهمته بعدل وأمانة . 
يجوز للمحكمة ان تعطى للحكمين مهلة أخري مرة واحدة لا تزيد عن ثلاثة اشهر فان لم يقدما تقرير هما اعتبرها غير متفقين.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 9', 'لا يؤثر فى سير الحكمين امتناع أحد الزوجين عن حضور مجلس التحكيم متى تم إخطاره.
وعلى الحكمين ان يعرفا أسباب الشقاق بين الزوجين ويبذلا جهدها فى الإصلاح بينهما على أية طريقة ممكنة.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 10', 'إذا عجز الحكمين عن الإصلاح
فان كانت الإساءة كلها من جانب الزوج اقترحا الحكمان التطليق بطلقة بائنة دون مساس لشيء من حقوق الزوجة المترتبة على الزواج والطلاق
وإذا كانت الإساءة كلها من جانب الزوجة اقترحا الحكمان التطليق نظير بدل مناسب يقر انه تلتزم به الزوجة
وان كانت الإساءة مشتركة اقترحا التطليق دون بدل او ببدل يتناسب مع نسبة الإساءة
وان جهلا الحال فلم يعرف المسيء منهما اقترح الحكمان تطليقا دون بدل .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 11', 'على الحكمين ان يرفعا تقريرهما الى المحكمة مشتملا على الأسباب التي بنى عليها فان لم يتفقا بعثتهما مع ثالث له خبرة بالحال وقدرة على الإصلاح وحلفته اليمين المبينة فى المادة (8) وإذا اختلفوا او لم يقدموا تقريرهم فى الميعاد المحدد سارت المحكمة فى الإثبات وان عجزت المحكمة عن التوفيق بين الزوجين وتبين لها استحالة العشرة بينهما واصرت الزوجة على الطلاق قضت المحكمة بالتطليق بينهما بطلقة بائنة مع إسقاط حقوق الزوجة المالية كلها او بعضها وإلزامها بالتعويض المناسب ان كان لذلك كله مقتضى .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 11', 'مكرر (مضافة) 
على الزوج أن يقر فى وثيقة الزواج بحالته الاجتماعية , فإذا كان متزوجا فعليه ان يبين فى الإقرار اسم الزوجة او الزوجات اللاتي فى عصمته ومحال إقامتهن, وعلى الموثق إخطارهن بالزواج الجديد بكتاب محل مقرون بعلم الوصول.

ويجوز للزوجة التي تزوج عليها زوجها ان تطلب الطلاق منه إذا لحقها ضرر مادي او معنوي يتعذر معه دوام العشرة بين أمثالها ولو لم تكن قد اشترط عليه فى العقد الا يتزوج عليها, فإذا عجز القاضى عن الإصلاح بينهما طلقها عليه طلقة بائنة.

ويسقط حق الزوجة فى طلب التطليق لهذا السبب بمضي سنة من تاريخ علمها بالزواج بأخرى إلا إذا كانت قد رضيت بذلك صراحة او ضمنا, ويتجدد حقها فى طلب التطليق كلما تزوج عليها بأخرى, وإذا كانت الزوجة الجديدة لم تعلم انه متزوج بسواها ثم ظهر انه متزوج فلها ان تطلب التطليق كذلك.

إنذار الطاعة', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 11', 'مكرر ثانيا
إذا امتنعت الزوجة عن طاعة الزوج دون حق توقف نفقة الزوجة من تاريخ الامتناع 

وتعتبر ممتنعة دون حق إذا لم تعد لمنزل الزوجية بعد دعوة الزوج إياها للعودة بإعلان على يد محضر لشخصها او من ينوب عنها وعليه أن يبين فى هذا الإعلان المسكن.

وللزوجة الاعتراض على هذا أمام المحكمة الابتدائية خلال ثلاثين يوما من تاريخ هذا الإعلان وعليها أن تبين فى صحيفة الاعتراض الأوجه الشرعية التي تستند إليها فى امتناعها عن طاعته وإلا حكم بعدم قبول اعتراضها. 

ويعتد بوقف نفقتها من تاريخ انتهاء ميعاد الاعتراض اذا لم تتقدم به فى الميعاد.

وعلى المحكمة عند نظر الاعتراض , او بناء على طلب أحد الزوجين, التدخل لإنهاء النزاع بينهما صلحا باستمرار الزوجية وحسن المعاشرة.

فإذا بان لها ان الخلاف مستحكم وطلبت الزوجة التطليق اتخذت المحكمة إجراءات التحكيم الموضحة فى المواد من 7 الى 11 من هذا القانون.
التطليق لغيبة الزوج او حبسه', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 12', 'إذا غاب الزوج سنة فاكثر بلا عذر مقبول جاز لزوجته ان تطلب الى القاضى تطليقها تطليقا بائنا إذا تضررت من بعده ولو كان له مال تستطيع الإنفاق منه.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 13', 'إن أمكن وصول الرسائل الى الغائب ضرب له القاضى أجلا واعذر إليه بأنه يطلقها فإذا انقضى الأجل ولم يفعل ولم يبدى عذرا مقبولا فرق القاضى بينهما بطلقة بائنة.

وإذا لم يمكن وصول الرسائل الى الغائب طلقها القاضى عليه بلا عذر او ضرب اجل.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 14', 'لزوجة المحبوس المحكوم عليه نهائيا بعقوبة مقيدة للحرية مدة ثلاث سنين فاكثر ان تطلب الى القاضى بعد مضى سنة من حبسه التطليق عليه بائنا للضرر ولو كان له مال تستطيع الإنفاق منه.
دعوى النسب', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 15', 'لا تسمع عند الإنكار دعوى النسب لولد زوجة ثبت عدم التلاقي بينها وبين زوجها من حين العقد, ولا لولد زوجة آتت به بعد سنة من غيبة الزوج عنها , ولا لولد المطلقة والمتوفى عنها زوجها اذا آتت به لأكثر من سنة من وقت الطلاق او الوفاة.

تقدير النفقة و نفقة العدة', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 16', 'تقدر نفقة الزوجة بحسب حال الزوج وقت استحقاقها يسرا أو عسرا على إلا تقل النفقة فى حالة العسر عن القدر الذي يفي بحاجتها الضرورية.

وعلى القاضى فى حالة قيام سبب استحقاق النفقة وتوافر شروطه ان يفرض للزوجة ولصغارها منه فى مدى أسبوعين على الأكثر من تاريخ رفع الدعوى نفقة مؤقتة (بحاجاتها الضرورية) بحكم غير مسبب واجب النفاذ فورا الى حين الحكم بالنفقة بحكم واجب النفاذ .

للزوج ان يجرى المقاصة بين ما أداه من النفقة المؤقتة وبين النفقة المحكوم بها عليه نهائيا, بحيث لا يقل ما تقبضه الزوجة وصغارها عن القدر الذي يفي بحاجتهم الضرورية.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 17', 'لا يسمع الدعوى لنفقة عدة لمدة تزيد على سنة من تاريخ الطلاق.
كما انه لا تسمع عند الإنكار دعوى الإرث بسبب الزوجية لمطلقة توفى زوجها بعد سنة من تاريخ الطلاق.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 18', 'لا يجوز تنفيذ حكم بنفقة صادر بعد العمل بهذا القانون لمدة تزيد على سنة من تاريخ الطلاق ولا يجوز تنفيذ حكم صدر قبل العمل بهذا القانون لمدة بعد صدوره إلا بمقدار ما يكمل سنة من تاريخ الطلاق.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 18', 'مكرر
الزوجة المدخول بها فى زواج صحيح إذا طلاقها زوجها دون رضاها ولا بسبب من قبلها تستحق فوق نفقة عدتها متعة تقدر بنفقة سنتين على الأقل وبمراعاة حال المطلق يسرا أو عسرا ومدة الزوجية ويجوز ان يرخص للمطلق فى سداد هذه المتعة على أقساط.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 18', 'مكرر ثانيا 
إذا لم يكن للصغير مال فنفقته على أبيه.

وتستمر نفقة الأولاد على أبيهم الى ان تتزوج البنت او تكسب ما يكفى نفقتها والى ان يتم الابن الخامسة عشر من عمره قادرا على الكسب المناسب, فان أتمها عاجزا عن الكسب لآفة بدنية او عقلية او بسبب طلب العلم الملائم لأمثاله ولاستعداده, او بسبب عدم تيسر هذا الكسب استمرت نفقته على أبيه.

ويلتزم الأب بنفقة أولاده وتوفير المسكن لهم بقدر يساره وبما يكفل للأولاد العيش فى المستوى اللائق بأمثالهم.

وتستحق نفقة الأولاد على أبيهم من تاريخ امتناعه عن الإنفاق عليهم.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 18', 'مكرر ثالثا (مضافة)
ألغيت بحكم المحكمة الدستورية الصادر بجلسة 6/1/1996 فى القضية 5 لسنة 8 ق. دستورية 

المهــر', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 19', 'إذا اختلف الزوجان فى مقدار المهر فالبينة على الزوجة فان عجزت كان القول للزوج بيمين إلا إذا ادعى ما لا يصح ان يكون مهرا لمثلها.
وكذلك الحكم عند الاختلاف بين أحد الزوجين وورثة الأخر او بين ورثتهما.

سن الحضانة', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 20', 'ينتهي حق حضانة النساء ببلوغ الصغير سن العاشرة وبلوغ الصغيرة اثنتي عشرة سنة, ويجوز للقاضى بعد هذه السن إبقاء الصغير حتى تتزوج فى يد الحاضنة دون اجر حضانة إذا تبين ان مصلحتها تقتضي ذلك.
ولكل من الأبوين الحق فى رؤية الصغير او الصغيرة وللأجداد مثل ذلك عند عدم وجود الأبوين.
وإذا تعذر تنظيم الرؤية اتفاقا نظمها القاضى على ان تتم فى مكان لا يضر بالصغير او الصغيرة او الصغيرة نفسيا.
ولا ينفذ حكم الرؤية قهرا, ولكن إذا امتنع عن بيده الصغير عن تنفيذ الحكم لغير عذر انذره القاضى فان تكرر ذلك جاز للقاضى بحكم واجب النفاذ نقل الحضانة مؤقتا الى من يليه من أصحاب الحق فيها لمدة يقدرها.

ويثبت الحق فى الحضانة للام ثم للمحارم من النساء, مقدما فيه من يدلى بالام على من يدلى بالاب, ومعتبرا فيه الأقرب من الجهتين على الترتيب التالي :
الام, فأم الام وان علت, فأم الأب وان علت, فالأخوات الشقيقات, فالأخوات لام, فالأخوات لاب, فبنت الأخت الشقيقة, فبنت الأخت لام, فالخالات بالترتيب المذكور فى الأخوات, فبنت الأخت لاب, فبنت الاخ بالترتيب المذكور, فخالات الام بالترتيب المذكور, فخالات الأب بالترتيب المذكور, فعمات الام بالترتيب المذكور, فعمات الاب بالترتيب المذكور.

فإذا لم توجد حاضنة من هؤلاء النساء او لم يكن منهن أهل للحضانة او انقضت مدة حضانة النساء انتقل الحق فى الحضانة الى العصبات من الرجال بحسب ترتيب الاستحقاق فى الإرث, مع مراعاة تقديم الجد الصحيح على الاخوة.

فإذا لم يوجد أحد من هؤلاء, انتقل الحق فى الحضانة الى محارم الصغير من الرجال غير العصبات على الترتيب الأتي:
الجد لام, ثم الاخ لام, ثم ابن الاخ لام, ثم العم ثم الخال ثم الشقيق, فالخال لاب فالخال لام.

المفقود', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 21', 'يحكم بموت المفقود الذى يغلب عليه الهلاك بعد اربع سنوات من تاريخ فقده, يعتبر المفقود ميتا بعد مضى سنة من تاريخ فقده فى حالة ما ثبت انه كان على ظهر سفينة غرقت او كان فى طائرة سقطت, او كان من افراد القوات المسلحة وفقد اثناء العمليات الحربية. ويصدر رئيس مجلس الوزراء او وزير الدفاع بحسب الأحوال وبعد التحري واستظهار القرائن التى يغلب معها الهلاك قرارا بأسماء المفقودين اعتبروا أمواتا فى حكم الفقرة السابقة ويقوم هذا القرار مقام الحكم بموت المفقود.

واما فى جميع الأحوال الأخرى يفوض تحديد المدة التي يحكم بموت المفقود بعدها الى القاضى على الا تقل عن اربع سنوات وذلك بعد التحري عنه بجميع الطرق الممكنة الموصلة الى معرفة ان كان المفقود حيا او ميتا.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 22', 'بعد الحكم بموت المفقود أو نشر قرار رئيس مجلس الوزراء او قرار وزير الدفاع باعتباره ميتا على الوجه المبين فى المادة السابقة تعتد زوجته عدة الوفاة وتقسم تركته بين ورثته الموجودين وقت صدور الحكم او نشر القرار فى الجريدة الرسمية كما تترتب كافة الآثار الأخرى .

أحكام عامة', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 23', 'المراد بالنسبة فى المواد من 12 الى 18 هي السنة التي عدد أيامها 365 يوما.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 23', 'مكرر (مضافة) 

يعاقب المطلق او الزوج بالحبس مدة لا تجاوز ستة اشهر وبغرامة لا تجاوز مائتي جنيه او بإحدى هاتين العقوبتين إذا خالف أيا من الأحكام المنصوص عليها فى المادة الخامسة مكررا والسادسة مكررا من هذا القانون.

كما يعاقب الزوج بالعقوبة ذاتها إذا أدلى للموثق بيانات غير صحيحة عن حالته الاجتماعية او محال إقامته او محال إقامة زوجاته او مطلقته على ما هو مقرر فى المادة 11 مكرر.

ويعاقب الموثق مدة لا تزيد على شهر وبغرامة لا تجاوز خمسين جنيها إذا أخل بأي من الالتزامات التي فرضها عليه القانون ويجوز أيضا الحكم بعزله او وقفة عن عمله لمدة لا تجاوز لا تجاوز سنة.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 24', 'تلغى المواد 12,7,3 من القانون 25 لسنة 1920 التى تتضمن أحكاما بشان النفقة ومسائل متعلقة بالأحوال الشخصية.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون الخلع', 'المادة 25', 'على وزير الحقانية هذا القانون , ويعمل به من تاريخ نشره فى نشره فى الجريدة الرسمية.

(صدر القانون بسراي عابدين فى 28 من رمضان 1347 هـ والموافق 10 من مارس 1939م و نشر القانون بالوقائع المصرية بتاريخ 14 من شوال 1347هـ الموافق 25 من مارس 1939م. بالعدد رقم 27 لسنة 1939م 

