INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون العقوبات المصري', 'المادة 10', '-
الجنايات هى الجرائم المعاقب عليها بالعقوبات الاتية:
الاعدام .
الاشغال الشاقة المؤبدة.
الاشغال الشاقة المؤقتة.
السجن.', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون العقوبات المصري', 'المادة 11', '(1):-
