INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قانون العقوبات المصري', 'المادة 265', '-
كل من اعطى عمدا لشخص جواهر غير قاتلة فنشأ عنها مرض او عجز وقتى عن العمل يعاقب طبقاً لاحكام المواد 240 و 241 و 242 على حسب جسامة ما نشأ عن الجريمة ووجود سبق الاصرار على ارتكابها او عدم وجودة .', 'flashsa-lawyers');
