INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 65', 'يحكم بالحجر علي البالغ للجنون او للعته او للسفه او للغفله ولا يرفع الحجرالا بحكم وتقيم المحكمة علي من يحجر علية قيما لادارة امواله وفقا للاحكام المقررة في هذا القانون .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 66', 'النفقات اللازمة للعناية بالمحجوزعلية مقدمة علي ما عداها ز', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 67', 'يجوز للمحجوز علية للسفة او للغفلة باذن من المحكمة ان يتسلم امواله كلها او بعضها لادرتها وفي هذه الحالة تسرى عليه الاحكام التي تسرى فيشان القاصر الماذون .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 68', 'تكون القوامة للابن البلغ ثم للاب ثم للجد ثم لمن تختارة المحكمة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 69', 'يشترط في القيم ما يشترط في الوصى وفقا للمادة 27 ومع ذلك لا يحول قيام احد السببين المنصوص عليهما في البندين 1 , 4 من المادة المذكورة دون تعيين الابن او الاب او الجد اذا رات المحكمة مصلحة في ذلك .

الفصل الثانى
في المساعدة القضائية', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 70', 'اذا كان لشخص اصم ابكم او اعمى اصم اعم ابكم وتعذر عليه بسبب ذلك التعبير عن اردته جاز للمحكمة ان تعين له مساعدا قضائيا يعاونه في التصرفات النصوص عليها في المادة 39 :
ويجوز لها ذلك ايضا اذا كان يخشى من انفراد الشخص بمباشرة التصرف في ماله بسبب عجز جسمانى شديد .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 71', 'يشترك المساعد القضائى في التصرفات المشار اليها في المادةالسابقة واذا امتنع عن الاشتراك في تصرف جاز رفع الامر للمحكمة فان رات ان الامتناع في غير محله اذنت المحكوم بمساعدته في ابرامه او عينت شخصا اخر للمساعدة في ابرامه وفقا للتوجيهات التى تبينها في قرارها .
واذا كان عدم قيام الشخص الذى تقررت مسعدته قضائيا بتصرف معين يعرض امواله للخطر جاز المساعدة ورفع الامر الي المحكمة ولها ان تامر بعد التحقيق بانفراد المساعد باجراء هذا التصرف .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 72', 'يسرى علي المساعد القضائى حكم المادة 50 من هذا القانون .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 73', 'يعتبر المساعد القضائى في حكم النائب في تطبيق احكام المواد 108 , 382 , 479 من القانون المدنى 

الفصل الثالث . في الغيبه .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 74', 'تقيم المحكمة وكيلا عن الغائب كامل الاهلية في الاحوال الاتية :
متى كان قد انقضت مدة سنه او اكثر علي غيابه وترتب علي ذلك تعطيل مصالحة.
اولا : اذا كان مفقودا لا تعرف حياته او مماته .
ثانيا : اذا لم يكن له محل اقامه ولا موطن معلوم او كان له محل اقامة او موطن معلوم خارج المملكة المصرية . واستحال علية ان يتولى شئونه بنفسه او ان يشرف علي من ينيبة في ادارتها .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 75', 'اذا ترك الغائب وكيلا عاما تحكم المحكمة بتثبيته متى توافرات فيه الشروط الواجب توافرها في الوصى والا عينت غيره .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 76', 'تنتهى الغيبة بزوال سببها او بموت الغائب او بالحكم من جهة الاحوال الشخصية المختصة باعتباره ميتا .

الباب الثالث . احكام عامة
الفصل الاول . احكام مشتركة في الوصايه والقوامة والغيبة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 77', 'تحسب المدد المنصوص عليها في هذا القانون بالتقويم الميلادى .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 78', 'يسرى على القوامة والوكالة علي الغائبين الاحكام المقررة في شان الوصايه علي القصر ويسرى علي القوامة والوكلاء عن الغائبين الاحكام المقررة في شان الاوصياء .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 79', 'يسر في شان قسمة مال الغائب والمحجوز عليه ما يسرى في شان قسمة القاصر من احكام .

الفصل الثانى . في المشرف', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 80', 'يجوز تعيين مشرف مع الموصى ولو كان مختارا زكذلك مع القيم الوكيل عن الغائب .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 81', 'يراقب المشرف النائب عن عديم الاهلية او الوكيل عن الغائب في ادارته وعليه ابلاغ المحكمة او النيابة كل امر تقتضى المصلحة رفعه اليهما .
وعلى النائب او الوكيل اجابة المشرفين الي كل ما يطلبه من ايضاح عن ادارة الاموال وتمكينه من فحص الاوراق والمستندات الخاصة بهذه الاموال .
ويجب على المشرف اذا خلا مكان النئب او الوكيل ام يطلب الي المحكمة اقامة النائب او وكيل جديد والي ان يباشر هذا عمله يقوم المشرف من تلقاء نفسه بالاعمال التي يكون من تاجيلها ضرر .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 82', 'يسرى علي المشرف فيما ستعلف بتعينه وعزله وقبول استقالته واجره عن اعمالهومسئوليته عن تقصيره ما يسرى من احكام علي النائب او الوكيل علي حسب الاحوال .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 83', 'تقرر المحكمة انتهاء الاشراف اذا رات زوال داعيه .

الفصل الثالث . في الجزاءات', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 84', 'اذا قصر الوصى في الوجبات المفروضة عليه بمقتضى هذا القانون او وقف تنفيذ القرارات التي تصدرها المحكمة جاز لها ان تحكم عليه بغرامة لا تزيد علي مائة جنيه وحرمانه من اجرة كله او بعضه وعزله باحد هذه الجزاءات .
ويجوز للمحكمة ان تمنح القاصر هذه الغرامة او جزء منها . ويجوز اعفاء الوصى من الجزاء المالى كله او بعضه اذا نفذ الامر الذى ترتب عليه الحكم او قدم اعذارا تقبلها المحكمة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 85', 'اذا نفذ علي ممتلكات النائب المحكوم عليه بالغرامه ثم صدر حكم باقالته منها فلا حق له الا في استرداد ماحصل من التنفيذ . اما اذا رسا المزاد علي قلم الكتاب فلا يكون للمحكوم عليه الا استرداد العين بعد دفع مصروفات التنفيذ ما لم يكن هناك مانع فاذا وجد فلا يكون له استرداد الثمن الذى رسا به المزاد علي قلم الكتاب بعد خصم كامل المصرفات .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 86', 'اذا اخل النائب بواجب من الواجبات المفروضه عليه بمقتضىى هذا القانون كان مسئولا عما يلحق القاصر من ضرر بسبب ذلك وعلي كل حال يسال مسئوليته الوكيل باجر .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 87', 'تسرى احكام المواد السابقة علي القيم والمساعد القضائى والوكيل عن الغائب والوصى الخاص والوصى المؤقت .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 88', 'يعاقب بالحبس مدة لا تتجاوز سنه وبغرامه لا تزيد على مائة جنيه او باحدى هاتين العقوبتين كل وصى او قيم او وكيل انتهت نيابته اذا كان بقصد الاساءة قد امتنع عن تسليم اموال القاصر او المحجوز عليه او الغائب او اوراقه لمن حل محله من الوصية او القوامه او الوكاله وذلك ما لم ينص القانون علي عقوبة اشد .

قانون رقم 1 لسنة 2000 م
باصدار قانون تنظيم بعض اوضاع واجراءات
التقاضى في مسائل الاحوال الشخصية
باسم الشعب 
رئيس الجمهورية 
قرار مجلس الشعب القانون الاتى نصه , وقد اصدرناه :
المادة الاولى : 
تسرى احكام القانون المرفق علي اجراءات التقاضى في مسائل الاحوال الشخصية والوقف ويطبق فيما لم يرد بشانه نص خص فيه احكام قانون المرافعات المدنية والتجاريه واحكام قانون الاثبات في المواد المدنيه والتجاريه واحكام القانون المدنى في شان ادارة وتصفية التركات .
ويختص قاضى الاموال الوقتية بالمحكمة الابتدائيه دون غيره باصدار امر علي عريضة في مسائل الاحوال السخصية الاتيه :
التظلم من امتناع المرفق عن توثيق عقد الزواج اوعدم اعطاء شهادة مثبته للامتناع سواء للمصريين او الاجانب .
مد ميعاد جرد التركه بقدر ما يلزم لاتمام الجرد واذا كان القانون الواجب التطبيق حدد ميعادا له .
اتخاذ ما يراه لازما من الاجراءات التحفظيه او الوقتيه علي التركات التى لا يوجد فيها عديم اهليه او ناقصها او غائب .
غالاذن للنيابة للعامة في نقل النقود والاوراق الماليه والمستندات والمصوغات وغيرها مما يخشى عليه من اموال عديمى الاهليه او ناقصيها والغئبين الى خزانة احد المصارف او مكان امين .
المنازعات حول السفر الي الخارج بعد سماع لقوال ذوى الشان .

المادة الثانيه 
على المحاكم ان تحيل بدون رسوم ومن تلقاء نفسها ما يوجد لديها من دعاوى اصبحت بمقتضى احكام القانون المرفق من اختصاص محكام اخرى وذلك بالحالة التى يكون عليها , ةفى حالة غياب احد الخصوم يقوم قلم الكتاب باعلانه بامر الاحاله مع تكليفه بالحضور في الميعاد امام المحكمة التي احيلت البها الدعوى .
ولا تسرى احكام الفقرة السابقه على الدعاوى المحكوم فيها او الدعاوى المؤجله للنطق بالحكم فيها فتبقى خاضعة للنصوص السارية قبل العمل بهذا القانون .

المادة الثالثة 
تصدر الاحكام طبقا لقوانين الاحوال الشخصيه والوقف المعمول بها ويعمل فيما لم يرد بشانه نص في تلك القوانين بارجح الاقوال من مذهب الامام ابى حنيفه .
ومع ذلك تصدر الاحكام في المنازعات المتعلقه بالاحوال الشخصيه بين المصريين غير المسلمين المتحدى الطائفة والملة الذين كانت لهم جهات قضائية ملية منظمة حتى 31 ديسمبر سنة 1955 - طبقا لشريعتهم - فيما لا يخالف النظام العام .
المادة الرابعة 
تلغى لائحة ترتيب المحاكم الشرعيه الصادرة بالمرسوم بقانون رقم 78 لسنة 1931 , ويلغى الكتاب الرابع من قانون المرافعات المدنيه والتجاريه المضاف الى القانون رقم 77 لسنة 1949 , والقوانين ارقام 462 لسنة 1955 , 628 لسنة 1955 , 62 لسنة 1976 المشار اليها و ولائحة الاجراءات الواجب اتباعها في تنفيذ احكام الشرعيه الصادرة سنة 1907 , كما يلغى كل نص يخالف احكام القانون المرافق .
المادة الخامسة 
يصدر وزير العدل القرارات اللازمه لتنفيذ احكام القانون المرفق كما يصدر لوائح تنظيم شئون الاذونين والموثقين واهمالهم ونماذج الوثائق اللازمه لاداء هذه الاعمال .
المادة السادسة 
ينشر هذا القانون في الجريدة الرسميه , ويعمل به بعد شهر من اليوم التالى لتاريخ نشره .
يبصم هذا القانون بخاتم الدوله , وينفذ كقانون من قوانيها . 
