INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 1', 'تحسب المدد والمواعيد الاجرائية المنصوص عليها في هذا القانون بالتقويم الميلادى .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 2', 'تثبت اهلية التقاضى في مسائل الاحوال الشخصيه للولايه على النفس لمن اتم خمس عشرة سنة ميلاديا كامله متمتعا بقواه العقليه .
وينوب عن عديم الاهليه او ناقصها ممثله القانونى , فاذا لم يكن له من يمثله او كان هناك وجه لمباشرة اجراءات التقاضى بالمخالفة لراى ممثله او في مواجهته عينت المحكمة له وصى خصومه من تلقاء نةفسها او بناء علي طلب النيابة العامة او الغير .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 3', 'لا يلزم توقيع محام علي صحف دعاوى الاحوال الشخصية امام المحكمة الجزئية , فاذا رفعت الدعوى بغير توقيع محام علي صحيفتها كان للمحكمة عند الضرورة ان تندب محاميا للدفاع عن المدعى . ويحدد الحكم الصادر في الدعوى اتعابا للمحامى المنتدب . تتحملها الخزانه العامه , وذلك دون اخلال بالتزام مجالس النفقات الفرعية بتقديم المساعدات القضائية على النحوالمنصوص عليه في القانون رقم 17 لسنة 1983 بشان اصدار قانون المحاماة . وتعفى دعاوى النفقات وما في حكمها من الاجور والمصروفات بجميع انواعها من كافة الرسوم القضائيه في كل مراحل التقاضى ز', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 4', 'يكون للمحكمة في اطار تهيئة الدعوى للحكم تبصرة الخصوم في مواجهتم بما يتطلبه حسن سير الدعوى, ومنحهم اجلا لتقديم دفاعهم .
ولها ان تب اخصائيا اجتماعيا او اكثر لتقديم تقرير عن الحالة المعروضة عليها او عن مسالة فيها , وتححدد اجلا لتقديم التقرير لا يزيد على اسبوعين .
ويتم الندب من قوائم الاخصائين الاجتماعين التي تصدر بها قرار من وزير العدل بناء ترشيح وزير التامينات والشئون الاجتماعية .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 5', 'للمحكمة ان تقرر نظر المسائل المتعلقة بالاحوال الشخصية - مراعاة لاعتبارات النظام العام او الاداب - في غرفة المشورة وبحضور احد الاعضاء النيابة العامة متى كانت ممثلة في الدعوى , وتنطق الاحكام والقرارت في جلسة علنية .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 6', 'مع عدم الاخلال باختصاصات النيابة العامة برفع الدعوى في مسائل الاحوال الشخصية على وجة الحسبة المنصوص عليه في القانون رقم 3 لسنة 1996 , للنيابة العامة رفع الدعوى ابتداء في مسائل الاحوال الشخصية اذا تعلق الامر بالنظام العام او الاداب , كما يجوز لها ان تتدخل في دعاوى الاحوال الشخصية التى تختص بها المحاكم الجزئية .
وعلي النيابة العامة ان تتدخل في دعاوى الاحوال الشخصية والوقف التى تختص بها المحاكم الابتدائية او محاكم الاستئناف والا كان الحكم باطلا .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 7', 'لا تقبل عند الانكار دعوى الاقرار بالنسب او الشهادة علي الاقرار به بعد وفاة المورث الا اذا وجدت اوراق رسمية او مكتوبه جميعها بخط المتوفى وعليها امضاءة او ادلة قطعية جازمة تدل على صحة الادعاء .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 8', 'لا تقبل دعوى الوقف او شروطة او الاقرار به او الاستحقاق فيه او التصرفات الوارده عليه ما لم يكن الوقف ثابتا باشهاد مشهر وفقا لاحكام القانون .
ولا تقبل دعوى الوقف او الارث عند الانكار متى رفعت بعد مضى ثلاث وثلاثين سنة من وقت ثبوت الحق , الا اذا قام عذر حال دون ذلك .
واذا حكم بعزل ناظر الوقف او ضم ناظر اخر اليه , تعين المحكمة في الحالتين بحكم , واجب النفاذ ناظرا بصفه مؤقته الى ان يفصل في الدعوى بحكم نهائى .
 
 

الباب الثانى
اختصاص المحاكم بمساءل الاحوال الشخصية
الفصل الاول . الختصاص النوعى', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 9', 'تختص المحكمة الجزئية بنظر المسائل الواردة بهذه المادة وبمراعاة احكام المادة 52 من هذا القانون يكون حكمها في الدعوى قابلا للطعن بالاستئناف ما لم ينص القانون على نهايته وذلك كله علي الوجة التالى .
اولا - المسائل المتعلقة بالولاية علي النفسى .
الدعاوى المتعلقة بحضانة الصغير وحفظهورؤيته وضمنه والانتقال به .
الدعاوى المتعلقة بالنفقات وما حكمها من الاجور والمصروفات بجميع انواعها .
الدعاوى المتعلقة بالاذن للزوجة بمباشرة حقوقها القانون الواجب التطبيق يقضى بضرورة الحصول علي اذن الزوج لمباشرة تلك الحقوق .
دعاوى المهر والجهاز والدوطة والشبكة وما في حكمها ويكون الحكم نهائيا اذا كان المطلوب لا يتجاوز النصاب الانتهائى للقاضى الجزئى .
تصحيح القيود المتعلقة بالاحوال الشخصية فى وثائق الزواج والطلاق .
توثيق ما يتفق عليه ذو الشان امام المحكمة فيما يجوز شرعا .
الاذن بزواج من لا ولى له .
تحقيق الوفاة والوراثة والوصية الواجبة , ما لم يثر بشانها نزاع .
دعاوى الحبس لامتناع المحكوم عليه عن تنفيذ احكام النفقات وما في حكمها ويكون الحكم في ذلك نهائيا .
ثانيا . المسائل المتعلقة بالولاية علي المال
 متى كان المال المطلوب حمايته لا تتجاوز قيمته نصاب اختصاص المحكمة الجزئية .
تثبيت الوصى المختار وتعيين الوصى والمشرف والمدير ومراقبة اعمالهم والفصل في حساباتهم وعزلهم واستبدالهم .
اثبات الغيبة وانهاؤها وتعيين الوكبل عن الغائب ومراقبة اعماله وعزله واستبدالة .
تقرير المساعدة القضائية ورفعها وتعيين المساعد القضائى واستبداله ز
استمرار الولاية او الوصايه الى ما بعد سن الحادية والعشرين والاذن للقاصر بتسليم امواله لادالاتها وفقا لاحكام القانون والاذن له بمزاولة التجارة واجراء التصرفات التى يلزم للقيام بها الحصول على اذن , وسلب اى من هذه الحقوق او وقفها او الحد منها .
 تعيين ماذون بالخصومة عن القاصر او الغائب ولو لم يكن له مال .
 تقدير نفقة للقاصر من ماله والفصل فيما يقوم من نزاع بين ولى النفس او ولى التربية وبين الوصى فيما يتعلق بالانفاق علي القاصر او تربيتة او العنايه به .
اعفاء الولي من الحالات التى يجوز اعفاؤه فيها وفقا لاحكام قانون الولاية على المال .
 طلب تنحى الولى عن ولايته واستردادها .
الاذن بما يصرف للزوج القاصر في الاحوال التي يوجب القانون استئذان المحكمة فيها .
جميع الاموال الاخرى المتعلقة بادارة الاموال وفقا لاحكام القانون واتخاذ الاجراءات التحفظية والمؤقته الخاصة بها مهما كانت قيمة المال .
تعيين مصف للتركة وعزلة واستبداله والفصل في المنازعات المتعلقة بالتصفية متى كانت قيمة التركة لا تزيد علي النصاب اختصاص المحكمة الجزئية .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 10', 'تختص المحكمة الابتدائية بنظر دعاوىالاحوال الشخصية التى لا تدخل في اختصاص المحكمة الجزئية ودعاوى الوقف وشروطة والاستحقاق فية والتصرفات الواردة علية .
ويكون للمحكمة الابتدائية المختصة محليا بنظر دعوى الطلاق او التطليق او التفريق4 الجسمانى دون غيرعا , الحكم ابتدائيا في دعاوى النفقات او الاجور وما ي حكمها سواء للزوجة او الاولاد او الاقارب و وحضانة الصغير وحفظة ورؤيتة وضمنه والانتقال به ومسكن حضانته .
وتلتزم المحاكم الابتدائية والجزئية التى رفعت او ترفع امامها دعوى باى من هذه الطلباتا باحالتها الى تلك المحكمة حتى يصدر فيها حكم قطعى واحد .
وللمحكمة اثناء سير الدعوى ان تصدر احكاما مؤقته واجبة النفاذ بشان الرؤيه او بتقرير نفقة وقتيه تو تعديل ما عساها تكون قد قررته من نفقة بالزيادة او النقصان .
ولا يجوز الطعن علي تلك الاحكام المؤقته التى تصدر اثناء سير هذه الدعاوى الا بصدور الحكم النهائى فيها .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 11', 'تختص المحكمة الابتدائية التى يجرى في دائرتها توثيق عقد زواج الاجانب بالحكم فى الاعتراض علي هذا الزواج او طلب الحجر علي احد طرفى العقد اذا كان القانون واجب التطبيق يجعل الحجر سببا لزوال اهليته للزواج , ويترتب علي اقامة الدعوى وقف اتمام الزواج حتى يفصل نهائيا فيها .
كما تختص المحكمة الابتدائية بتوقيع الحجر ورفعة وتعيين القيم ومراقبة اعماله والفصل في حساباته وعزبه واستبداله , والاذن للمحجور علية بتسليم امواله لادارتها .
وفقا لاحكام القانون وساب هذا القانون وسلب هذا الحق منه , وتعيين ماذون بالخصومة عنه , وتقدير نفقة للمحجور علية في مالة و والفصل فيما يقوم من نزاع بين ولى النفس وولى التربية وبين القيم فيما يتعلق بالانفاق علي المحجور عليه .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 12', 'اذا قضت المحكو بسلب الولايه او وقفها عهدت بها الى من يلى من سابت ولايته او اوقفت وفقا للقانون الواجب التطبيق ثم الى من يلية بالتتابع , فان امتنع من عهد الية بها بعد اخطارة علي النحو المنصوص علية في المادة 40 من هذا القانون او شخص امين او لاحدى المؤسسات الاجتماعية .
وتسلم الاموال في هذه الحالة للنائب المعين بوصفة مديرا مؤقتا وذلك بعد جردها على النحو الوارد بالمادة 41 من هذا القانون .
وتتخذ النيابة العامة علي وجة السرع الاجراءات اللازمة لتعيين وصى علي المشمول بالولاية .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 13', 'تختص المحكمة التى تنظر المادة الاصلية دون غيرها باعتماد الحساب النقدم من النائب عن عديم الاهلية او ناقصها او الغائب , او المقدم من النائب عن عديم الاهلية او ناقصها او الغائب . او المقدم من المدير المؤقت والفصل في المنازعات المتعقة بهذا الحساب .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 14', 'تختص المحكمة التى قضت بانتهاء الولاية علي المال بنظر مادتى الحساب وتسليم الاموال , وذلك حتى تمام الفصل فيهما . كما تختص بنظر منازعات التنفيذ المتعلقة بالاحكام والقرارات الصادرة منها في هذا الشان .

الفصل الثانى
الاختصاص المحلى', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 15', 'يتحدد الماطن في مفهوم هذا القانون على النخو التالى المبين بالمواد 40 , 41 , 43 من القانون المدنى .
وبمراعاة احكام المادتين 10 , 11 من هذا القانون ينعقد الاختصاص للمحكمة التي تقع في دائرتها موطن المدعى علية , فان لم يكن له موطن في مصر تختص المحكمة التي يقع في دائرتها موطن المدعى .
واذا تعدد الدعى عليهم و كان الاختصاص للمحكمة التى يقع في دائرتها موطن احدهم ز
ومع ذلك يتحدد الاختصاص المحلى بنظر بعض مسائل الاحوال الشخصية , علي النحو الاتى :
تختص المحكمة التي يقع في دائرتها موطن المدعى او المدعى علية بنظر الدعوى المرفوعة من الاولاد او الزوجة او الوالدين او الحاضنة حسب الاحوال , في المواد الاتية :
أ - النفقات والاجور وما في حكمها ز
ب - الحضانة والرؤية والمسائل المتعلقة بهما .
جـ - المهر والجهاز والدوطة والشبكة وما في حكمها .
د - التطليق والخلع والابراء ةالفرقة بين الزوجين بجميع اسبابها الشرعية .
تختص المحكمة التي يقع في دائرتها اخر موطن للمتوفى في مصر بتحقيق اثبات ز الوراثة والوصايا زتصفية التركات فان لم يكن للمتوفى موطن في مصر يكون الاختصاص للمحكمة التى يقع في دائرتها احد اعيان التركة ز
يتحدد الاختصاص المحلى في مسائل الولاية علي المال علي النحم الاتى :
أ - في مواد الولاية بموطن الولى او القاصر وفى مواد الوصاية باخر موطن للمتوفى او للقاصر .
ب - في مواد الحجر والمساعدة القضائية بموطن المطلوب الحجر علية او مساعدته قضلئيا .
جـ - في مواد الغيبة باخر موطن للغائب .
فاذا لم يكن لاحد من هؤلاء موطن في مصر ينعقد الاختصاص بللمحكمة الكائن فى دائرتها مال الشخص المطلوب حمايته .
د - اذا تغير موطن القاصر او المجحوز عليه او المساعد قضائيا جاز للمحكمة بناء علي طلب ذوى الشان او النميابة العامة ان تحيل القضية الى المحكمة التي يقع في دائرتها الموطن الجديد .
هـ - تختص المحكمة التي امرت بسلب الولاية او وقفها بتعيين من يخلف الولى سواء كان وليا او وصيا - الا اذا رات من المصلحة احالة المادة الى المحكمة التى يوجد بدائرتها موطن القاصر .
فيما عدا قسمة اعيان الاوقاف المنتهية و يكون الاختصاص بنظر منازعات الوقف شروطة والتصرفات الواردة علية , للمحكمة الكائن بدائرتها اعيانه , او الاكثر قيمة اذا تعددت , او للمحكمة الكائن بدائرتها موطن ناظر الوقف او المدعى علية .

الباب الثالث
رفع الدعوى ونظرها
الفصل الاول في مسائل الولاية علي النفس', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 16', 'ترفع الدعوى في مسائل في مسائل الولاية علي النفس بالطرق المعتاد لرفع المنصوص عليه في قانون المرافعات المدنية والتجارية .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 17', 'لا تقبل الدعاوى الناشئة عن عقد الزواج اذا كانت من الزوجة تقل عن ست عشرة ميلادية , او كان سن الزواج يقل عن ثمانى عشرة سنة ميلادية وقت رفع الدعوى .
 ولا تقبل عند الانكار الدعاوى الناشئة عن عقد الزواج - في الوقائع اللاحقة علي او اغسطس سنة 1931 - ما لم يكن الزواج ثابتا بوثيقة رسمية , زمع ذلك تقبل دعوى التطليق او الفسخ بحسب او الاحوال ىدون غيرهما اذا كان الزواج ثابتا باية كتابة .
ولا تقبل دعوى الطلاق بين الزوجين متحدى الطئفة والملة الا اذا كانت شريعتهما تجيزة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 18', 'تلتزم المحكمة في دعاوى الولايه علي النفس بعرض الصلح علي الخصوم وبعض من تخلف عن جلسة الصلح - مع علمه بها بغير عدز مقبول رافضا له .
وفي دعاوى الطلاق والتطليق لا يحكم بها الا بعد ان تبذل المكمة جهدا في محاولة الصلح بين الزوجين وتعجز عن ذلك فان كان للزوجين ولد تلتزم المحكمة عرض الصلح مرتين علي الاقل بينهما تفصل بينهما مدة لا تقل عن ثلاثين يوما ولا تزيد عن ستين يوما .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 19', 'في دعاوى التطليق التي يوجب فيها القانون ندب حكمين يجب علي المحكمة ان تكلف كلا من الزوجين بتسمية حكم من اهلة - قدر الامكان - في الجلسة التالية علي الاكثر - فان تقاعس ايهما عن تعيين حكمة او تخلف عن حضور هذه الجلسة عينت المحكمة حكما عنه .
وعلي الحكمين المثول امام المحكمة في الجلسة التالية لتعيينهما ليقررا ما خلصا اليه معا , فان اختلف او تخلف ايهما عن الحضور تسمع المحكمة اقوالهما او اقوال الحاضر منهما بعد حلف اليمين .
وللمحكمة ان تاخذ بما انتهى اليه الحكمان او باقوال ايهما او بغير ذلك مما تستقية من اوراق الدعوى .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 20', 'للزوجين ان يتراضيا فيما بينهما علي الخلع و فان لم يتراضيا عليه واقامت الزوجة دعواها بطلبة وافتدت نفسها وخالعن زوجها بالتنازل عم حميع حقوقها المالية الشرعية وردت علية الصداق الذى اعطاه لها , حكمت المحكمة بتطليقها عليه . ولا تحكم المحكمة بالطليق للخلع الا بعد محاولة الصلح بين الزوجين , وندبهالحكمين لموالاة مساعى الصلح بينهما خلال مدة لاتجاوز ثلاثة اشهر وعلى الوجة المبين بالفقرة الثانية من المادة 18والفقرتين الاولى والثانية من المادة 19من هذا القانون وبعد انه تقرر الزوجة صراحة انها تبغض الحياة مع زوجها وانة لاسبيل لاستمرار الحياة الزوجية بينهما وتخشى الاتقيم حدود اللة بسب هذا البغض .

ويصح ان يكون مقابل الخلع اسقاط حضانة الصغار اة نفقتهم او اى حق من حقوقهم .
ويقع بالخلع فى جميع الاحوالطلاق بائن .
ويكون الحكم فى جميع الاحوال غير قابل بالطعن علية باى طريق من طرق الطعن .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 21', 'لايعتد فى اثبات الطلاق عند الانكار الابالاشهاد والتوثيف وعند طلب الاشهاد علية وتوثيقة يلتزم الموثق بتبصير الزوجين بمخاطر الطلاق ويدعوهما الى اختيار حكم من اهلة وحكم من اهلها للتوفيق بينهما فان اصر الزوجان معا على ايقاع الطلاق فورا او قرار معا ان الطلاق قد وقع او قرر الزوج انة اوقع الطلاق وجب توثيق الطلاق بعد الاشهاد علية .
وتطبق جميع الاحكام السابقة فى حالة طلب الزوجة تطليق نفسها اذا كانت قد احتفظات لنفسها بالحق فى ذلك فى وثيقة الزواج .
ويجب على الموثق اثبات ماتم من اجراءت فى تاريخ وقع كل منهما على النموذج المعد لذلك ولايعتد فى اثبات الطلاق فى حق اى من الزوجين الا اذا كان حاضر اجرات التوثيق بنفسة او بمن ينوب عنة او من تاريخ اعلانة بموجب ورقة رسمية .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 22', 'مع عدم الاخلال بحق الزوجة فى اثبات مراجعة مطلقها لها بكافة طرق الاثبات لايقبل عند الانكار ادعاء الزوج مراجعتة مطلقتة ما لم يعلنها لهذة المراجعة بورقة رسمية قبل انقضاء 60 يوما لمن تحيض وتسعين يوما لمن عدتها بلاشهر من تاريخ توثيق طلاقه لهل وذلك ما لم تكن حاملا او تقر بعدم انقضاء عدتها حتى اعلانها بمراجعة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 23', 'اذا كان دخل المطلوب الحكم علية بنفقتة او ما فى حكمها محل منازعة جدية ولم يكن فى اوراق الدعوى ما يكفى لتحديدة وجب على المحكمة ان تطلب من النيابة العامة اجراء التحقيق الذى يمنكها من بلوغ هذا التحديد .
وتباشر النيابة العامة بنفسها اجراء التحقيق فى هذا الشان .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 24', 'على طالب اشهادة الوفاة او الوارثة او الوصية الواجبة ان يقدم طابا بذلك الى المحكمة المختصة مرفقا بة ورقة رسمية تثبت الوفاة والا كان الطلب غير مقبول .
ويجب ان يشتمل الطلب على بيان اخر موطن للمتوفى واسماء الوارثة والموصى لهم بوصيةواجبة وموطنهم ان وجدوا وعلى الطالب ان يعلنهم بالحضور امام المحكمة فى الميعاد المحدد لنظر الطلب ويحقق القاضى الطلب بشهادة من يوثق به وله ان يضيف اليها التحريات الادارية حسبما يراه '' فاذا ما انكر احد الوررثة او الموصى لهم وصية واجبة وراى القاضى ان الانكار جدى . كان عليه يحيل الطلب الى المحكمة الابتدايئة المختصة للفصل فيه .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 25', 'يكون الاشهاد الذى يصدره القاضى وفقا لحكم لبمادة السابقة حجة في خصوص الوفاة والوراثة والوصية الواجبة ما لم يصدر حكم علي خلافة .
 
الفصل الثانى
في مسائل الولاية على المال', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 26', 'تتولى النيابة العامة رعاية مصالح عديم الاهلية ناقصيها والغائبين والتحفظ على اموالهم والاشراف علي ادارتها وفقا لاحكام هذا القانون .
لها ان تندب - فيما ترى اتخاذا من تدبير - احد مامورى الضبط القضائى .
كما يكون لها ان تستعين معاونين يلحقون بها القرار يصدرة وزير العدل بتعيين هؤلاء المعاونون من مامورى الضبط الضائى في خصوص الاعمال التى تناط بها اثناء تاديتهم لوظائفهم .
وللنيابة العامة ان تقدر نفقة وقتية من اموال مستحق النفقة الى حين الحكم بتقديرها .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 27', 'على الاقارب الذين كانوا يقيمون معالمتوفي في معيشة واحدة او اكبر الراشدين من الورثة ابلاغ النيابة العامة بواقعة وفاة شخص غائب اوعديم اهلية او ناقصها او حمل مستكين او وفاة الوالى او الوصى او القيم او الوكيل عن الغائب خلال ثلاثة ايام من تاريخ حصول الوفاة .
وعلى الاقارب ابلاغ النيابة العامة خلال ذات المدة عن فقد اهلية او غياب احد افراد الاسرة واذا كان مقيما معهم في معيشة واحدة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 28', 'علي الاطباء المعالجين والمديري المستشفيات والمصحات علي حسب للاحوال ابلاغ النيابةالعامة عن حالات فقد الاهلية الناشئة عن عاهة عقلية بمجرد ثبوت ذلك لديهم .
وعلي المختصين بالسلطات الادارية ابلاغ النيابة العامة متى تبين لهم اثناء تادية عملهم حالة من حالات فقد الاهلية علي النحو المشار اليه بالفقرة السابقة .
ومع عدم الاخلال باحكام قرار رئيس الجمهورية بالقانون رقم 205 لسنة 1995 في شان سرية الحساب بالبنوك . تاتزم اية حهة حكومية او غير حكومية بامداد النيابة العامة بما تحت يدها من معلومات تكون منتجة في تحديد دخل المطلوب منه النفقة .
ولا يجوز استخدام ماتسفر عنه هذه التحقيقات من معلومات في غير المادة التي أجريت بشأنها .
ويجب علي النيابة العامة ان تنهي التحقيق وترسلة مشفوعا بمذكرة موجزا بنتائج التي حصلت إليها في موعد لا يجاوز ثلاثون يوما من تاريخ وصول طلب المحكمة إليها .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 29', 'علي الوصي علي الحمل المستكن ابلاغ النيابة العامة بانقضاء مدة الحمل أو بانفصالة حيا أو ميتا .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 30', 'يعاقب علي مخالفة احكام المواد 27 ، 28 ، 29 من هذا القانون بغرامة لا تقل عن خمسين جنيه ولا تجاوز مأئة جنية ، فأذ كانت عدم التبليغ بقصد الاضرار بعديم الاهلية أو ناقصها أو الغائب أو غيرهم من زوية الشأن تكون العقوبة الحبس مدة لا تزيد علي سنة وبغرامة لا تقل عن مائة جنية ولا تجاوز ألف جنية أو بأحدي هاتين العقوبتين .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 31', 'يعاقب بالحبس كل من أخف بقصد الاضرار مالا مملوكا لعديم الاهلية أو الغائب .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 32', 'تقيد النيابة العامة طلبات الحجر والمساعدة القضائية واستمرار الولاية أو الوصاية وسلب الولاية أو الحد منها أو وقفها وسلب الاذن للقاصر أو المحجور علية أو الحد منه أثبات الغيبة والحد من سلطة الوكيل عن الغائب ومنع المطلوب للحجر علية أو سلب ولايتة من التصرف أو تقييد حريتة فيه ، وذلك يوم وساعة تقديم الطلب في سجل خاص .
ويقوم القيد في السجل مقام التسجيل ، وينتج أثرة من تاريخ اجراءة متي قضي بأجابة الطلب ، وعلي النيابة العامة شطب القيد إذا قضي نهائيا برفض الطلب .
ويصدر وزير العدل قرار بأجراءات القيد والشطب .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 33', 'علي النيابة العامة بمجرد ورود التبليغ إليها وفقا لحكام هذا القانون أن تتخذ أجراءات اللازمة للماحفظة علي حقوق الحمل المستكن أو عديم الاهلية أو ناقصها أو الغائب وأن تحصر مؤقتا مالهم من أموال ثابتة او منقولة او حقوق وما عليهم من التزامات في محضر يوقع علية ذوو الشأن .
وللنيابة العامة ان تتخذ الاجراءات الوقتية أو التحفظية اللازمة للمحافظة علي هذه الاموال وان تأمر بوضع الاختام عليها ، ولها بناء علي امر صادر من قاضي الامور الوقتية ان تنقل ان تنقل النقود والاوراق المالية والمستندات والمصوغات وغيرها مما يخشي علية إلي خزانة احد المصارف أو الي مكان امين .
وللنيابة العامة - عند الاقتضاء - ان تأذن لوصي التركة او منفذ الوصية او مديرها ان وجد او لاي شخص امين اخر بالصرف علي جنازة المتوفي والانفاق علي من تلزمة نفقتهم وادارة الاعمال التي يخشي عليها من فوات الوقت .
وللنيابة العامة ان تعدل عن أي قرار اتخذتة تطبيقا لاحكام هذه المادة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 34', 'للنيابة العامة بناء علي اذن مسبب من القاضى الجزئىدخول المساكن والاماكن اللازم دخولها لاتاذ الاجراءات التحفظية المنصوص عليها في هذا القانون ولها ان تندب لذلك - بامر مسبب يحدد فية المسكن او المكان - احد مامورى الضبط القضائى .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 35', 'لا يلزم اتباع الاجراءات المنصوص عليها في المادتين السابقتين اذا لم يتجاوز مال المطلوب حمايته ثلاثة الاف جنية , تتعدد بتعددهم , وفي هذه الحالة تسلم النيابة العامة المال الي من يقوم علي شئونه ما لم تر النيابة العامة اتباع الاجراءات المشار اليها بالضوابط والاوضاع المقررة بهاتين المادتين .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 36', 'يرفع الطلب الي المحكمة المختصة من النيابة العامة او ذوى الشان .
وفي الحالة الاخيرة يجب ان يشتمل الطلب المرفوع علي البيانات التي يتطلبها قانون الرافعات في صحيفة الدعوى وان يرفق بها المستندات المؤيده له , وعلى المحكمة ان تحيله الي النيابة العامة لابداء ملاحظاتها عليها كتابة خلال ميعاد تحدده لذلك .
وتقوم النيابة العامة - فيما لا تختص باصدار امر فيه - بتحديد جلسة المحكمة لنظر المحكمة لنظر الطلب مشفوعا بما اجرته من تحقيقات وما انتهت اليه من راى و واعلان من لم ينبه عليه امامها من ذوى الشان بالجلسة .
وللمحكمة ان تندب النيابة العامة لمباشرة اى اجراء من اجراءات التحقيق الذى تامر به .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 37', 'للمحكمة والنيابة العامة ان تدعو من ترى فائدة من سماع اقواله في كل تحقيق تجريه , فان تخلف عن الحضور بالجلسة المحددة او امتنع عن الادلاء باقوال دون مبرر قانونى - جاز الحكم عليه بغرامة لا تجاوز مائة جنية , فان لم يحضر جاز للمحكمة وللنيابة العامة ان تامر باحضارة .
وللمحكمة ان تقبل المحكوم عليه من الغرامة كلها او بعضها اذا ابدى عذرا مقبولا .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 38', 'اذا رات رات النيابة العامة ان طلب توقيع الحجر او سلب الولاية او الحد منها او وقفها او اثبات الغيبة يقتضى اتخاذ اجراءات تحقيق تستغرق فترة من الزمن يخشى خلالها من ضياع حق اومال , رفعت الاملا للمحكمة لتاذن باتخاذ ما تراه من اجراءات تخفظية او لتامر بمنع المقدم من ادارتها او تعيين مدير مؤقت يتولى ادارة تلك الاموال .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 39', 'على النيابة العامة ان تقدم للمحكمة مذكرة مسبة بمن ترشحة عن عديم الاهلية او ناقصها او عن الغائب او من ترشحه مساعدا قضائيا , وذلك خلال ثمانية ايام علي الاكثر من تايخ ابلاغهم بالسبب الموجب لتعيينة.
وتعين المحكمة النائب او المساعد القضائى بعد اخذ راى ذوى الشان .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 40', 'تخطر النيابة العامة الوصى او القيم او الوكيل عن الغائب او المساعد القضائى او المدير المؤقت بالقرار الصادر بتعيينه اذا صدر في غيبته , وعلي من يرفض التعيين ابلاغ النيابة العامة كتابة برفضة خلال ثمانية ايام من تاريخ علمه بالقرار والا كان مسئولا عن المهام الموكلة اليه من تاريخ العام .
وفي حالة الرفض تعيين المحكمة بدلا منه علي وجه السرعة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 41', 'تقوم النيابة العامةبعد صدور قرار المحكمة بتعين النائب , بمجرد اموال عديم الاهلية او ناقصها او الغائب بمحضر يحرر من نسختين .
ويتبع في الجرد الاحكام والاجراءات التي يصدر بها قرار من وزير العدل ويدعى لحضور الجرد جميع ذوى الشان والقاصر الذى اتم خمس عشرة سنه ميلادية اذا رات النيابة العامة ضرورة لحضورة .
وللنيابة العامة ان تستعين باهل الخبرة في جرد الاموال وتقيمها وتقدير الديون وتسلم الاموال بعد انتهاء الجرد الى النائب المعين من المحكمة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 42', 'ترفع النيابة العامة محضر الجرد الى المحكمة للتصدية عليه بعد التحقق من صحة البيانات الواردة فيه .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 43', 'يجب علي النيابة العامة عند عرض محضر الجرد الى المحكمة للتصديق عليه ان ترفع مذكرة برايها في المسائل الاتيه بحسب الاحوال :
الاستمرار في الملكية الشائعة او الخروج منها وفي استغلال المحال التجارية او الصناعية او المكاتب المهنية او تصفيتها ووسائل الوفاء بالديون والقرارات المنفذه لذلك .
تقدير النفقة الدائمة اللازمة للقاصر او المحجوز عليه .
اتخاذ الطرق المئدية حسن ادارة الاموال وصيانتهاى .
وتلتزم المحكمة بالتصديق علي محضر الجرد وبالفصل في المسائل المشار اليها علي وجه السرعة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 44', 'للمحكمة ولو من تلقاء نفسها ان تعدل عن اى قرار اصدرته في المسائل المبينة في المادة السابقة اة عن اى اجراء من الاجراءات التحفظية اذا تبين ما يدعو لذلك .
ولا يمس عدول المحكمة عن قرار سبق ان اصدرته بحقوق الغير حسن النية الناشئة عن اى اتفاق .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 45', 'اذا عينت المحكمة مصفيا قبل التصديق علي محضر الجرد يتولى المصفى جرد التركة كلها ويحرر محضرا تفصيليا بما وما عليها بواقعة هو وعصو النيابة العامة والنائب المعين ومن يكون حاضرا من الورثه اراشدين واذا عين المصفى بعد التصديق علي محضر الجرد يقوم النائب عن عديم الاهلية او ناقصها او عن الغائب بتسليم نصيب الاخير في التركة الي المصفى بمحضر بوقعة هو والمصفى وعضو النيابة العامة والنائب المعين ومن يكون حاضرا من الورثة الراشدين وذلك وذلك ما لم يرى المصفى ابقاء المال كله او بعضة تحت يد النائب لحفظة وادارته مؤقتا حتى تتم التصفيه ويثبت ذلك علي نسختى محضر الجرد ويوقع عليه الاشخاص السابق ذكرهم وبعد انتهاء التصفية يسام ما يؤول من التركة الي النائب عن عديم الاهلية او ناقصها او عن الغائب مع مراعاة الاجراءات المنصوص عليها في هذا القانون .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 46', 'يجب على النائب عن عديم الاهلية او ناقصها او عن الغائب او المدير المؤقت ان يودع قلم المحكمة حسابا عن ادارته مشفوعا بالمستندات التي تؤيدة في الميعاد المحدد قانونا وكلما طلبت منه محكمة ذلك في الميعاد الذى تحددة فاذا انقضى الميعاد ولم يقدم الحساب جاز للمحكمة ان تحكم علية بغرامة لا تزيد على خمسمائة حنيه فان تقرر منه ذلك جاز ان تحكم علية بغرامة لا تزيد على الف جنية وذلك دون اخلال بالجزاءات الاخرى المنصوص عليها قانونا واذا قدم النائب الحساب وابدى عذرا عن التاخير قبلته المحكمة جاز لها ان تقبلة من كل الغرامة او بعضها وعلى المحكمة ان تامر مؤقتا بايداع المبالغ التى لا ينازع مقدم الحساب في ثبوتها في ذمته دون ان يعتبر ذلك مصادقة علي الحساب وتفصل المحكمة في صحة الحساب المقدم اليها ويجب ان يشمل القرار النهائى الذى تصدرة المحكة بشان الحساب الامر بالزام مقدمةباداء المبلغ المتبقى فى ذمتة وايداعه خزانة المحكة في ميعاد تحددة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 47', 'للنيابة العامة ان تصرح للنائب عن عديم الاهلية او ناقصها او عن الغائب بالصرف من الاموال السائلة لاى من هؤلاء دون الرجوع الي المحكمة بما لا يجوز زيادته الى ثلاث الاف جنية بقرار من المحامى العام المختص وذلك لمرة واحدة كل ستة اشهر .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 48', 'لا يقبل طلب استردلد الولاية او رفع الحجر او المساعدة القضائية او رفع الوصاية او الولاية او اعادة الاذن للقاصر او المحجور علية الا بعد انقضاء سنة من تاريخ القرار النهائى الصادر برفض طلب سابق .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 49', 'يجوز لذوى الشان الاطلاع على الملفات والدفاتر والسجلات والاوراق المنصوص عليها في المواد السابقة كما يجوز لكل شخص الاطلاع على السجلات وفي الحالتين تسلم لاى منهم صور او شهادات بمضمون ما اثبت فيها من المحكمة او النيابة العامة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 50', 'يكون لنفقات حصر الاموال ووضع الاختام والجرد والادارة حق امتياز في مرتبة المصروفات القضائية .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 51', 'للمحكمة ان تامر باضافة كل الرسوم او بعضها او المصاريف على عاتق الخزانة العامة .
 
الباب الرابع
القرارات والاحكام والطعن عليها
أولا إصدار القرارات :', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 52', 'تسرى على القرارات التى تصدر فى مسائل الولاية على المال القواعد الخاصة بالاحكام .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 53', 'يجب على المحكمة أن تودع قلم الكتاب أسباب القرارات القطعية الصادرة فى مواد الحجر والمساعدة القضائية والولاية والغيبة والحساب والإذن بالتصرف وعزل الوصى والقرارات الصادرة وفقا لحكم المادة 38 من هذا القانون وذلك فى ميعاد ثمانية ايام من تاريخ النطق به اذا صدرت من محكمة جزئية و خمسة عشرة يوما اذا صدرت من غيره وفيما عدا ذلك من قرارات تصدر فى مسائل الولاية على المال يجوز للمحكمة تسبيب هذه القرارات أو بالاتفاق بالتوقيع على محضر الجلسة المشتمل على المنطوق .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 54', 'تكون القرارات الصادرة من محكمة أول درجة بصفة ابتدائية فى مسائل الولاية على المال واجبة النفاذ ولو مع حصول استئنافها عدا تلك الصادرة فى المسائل الاتية :
الحساب .
رفع الحجر وانهاء المساعدة القضائية .
رد الولاية 
اعادة الاذن لقاصر أو للمحجور عليه بالتصرف أو الإدارة .
ثبوت الرشد بعد القرار باستمرار الوصاية أو الولاية .
الإذن بالتصرف للنائب عن عديم الأهلية أو ناقصها أو عن الغائب .
وللمحكمة المنظور أمامها الاستئناف أن تأمر بوقف التنفيذ مؤقتا حتى يفصل فى الطعن .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 55', 'يكون فرار المحكمة نهائيا اذا صدر فى تصرفات الأوقاف بالإذن بالخصومة أو فى طلب الاستدانة أو التأجير لمدة طويلة أو تغيير المعالم أو طلب الاستبدال أو بيع العقار الموقوف لسداد دينه ، اذا كان موضوع الطلب أو قيمة العين فى محل التصرف لا يزيد على خمسة ألاف جنيه .
ثانيا الطعن على الأحكام والقرارات :', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 56', 'طرق الطعن فى الأحكام والقرارات المبينة فى هذا القانون هى الاستئناف والنقض والتماس اعادة النظر وتتبع فيما لم يرد بها حكم خاص فى المواد الاتية القواعد والاجراءات المنصوص عليها فى قانون المرافعات المدنية والتجارية .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 57', 'يكون لللنيابة العامة فى جميع الأحوال الطعن بطريق الاستئناف فى الأحكام والقرارات الصادرة فى الدعاوى التى يوجب القانون أو يجيز تدخلها فيها ويتبع فى الطعن على الأحكام المنصوص عليها فى قانون المرفعات المدنية والتجارية .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 58', 'تنظر المحكمة الاستئنافية الدعاوى بالحالات التى كانت عليها قبل صدرو الحكم المستأنف بالنسبة لما رفع عنه الاستئناف فقط ومع ذلك يجوز مع بقاء الطلبات الأصلية على حالها تغيير أسبابها أو الإضافة اليها كما يجوز ابداء طلبات جديدة بشرط أن تكون مكملة للطلبات الأصلية أو مترتبة عليها أو متصلة بها اتصالا لا يقبل التجزئة وفى حالتان تلتزم المحكمة الاستئنافية بمنح الخصم أجلا مناسبا للرد على الأسباب أو الطلبات الجديدة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 59', 'يترتب على الطعن بالاستئناف فى الحكم القطعى الصادر وفقا لحكم المادة 1 من هذا القانون طرح ما فصل فيه هذا الحكم على محكمة الاستئناف وحتى تصدر هذا المحكمة حكمها النهائى يجوز لها اصدار حكم مؤقت واجب النفاذ بشأن الرؤية أو بتقرير النفقة أو بتعديل النفقة التى قام بها الحكم المطعون فيه بالزيادة أو النقصان .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 60', 'مع عدم الإخلال بحقوق الغير حسن النية يعد استئناف الحكم أو القرار الصادر فى مادة من مواد الولاية على الولاية المال استئنافا للمواد الاخرى التى لم يسبق استئنافها وترتبط بالحكم أو القرار المستأنف ارتباطا يتعذر معه الفصل فى الاستئناف دون اعادة الفصل فيه .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 61', 'ميعاد الاستئناف ستون يوما لمن لا موطن له فى مصر دون اضافة ميعاد مسافة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 62', 'للخصوم والنيابة العامة الطعن بالنقض فى الحكام الصادرة من محاكم الاستئناف كما يكون لها الطعن بالنقض فى القرارات الصادرة من هذه المحاكم فى مواد الحجر والغيبة والمساعدة القضائية وعزل الوصى وسلب الولاية أوقفها أو الحد منها أو ردها واستمرار الولاية أو الوصاية و الحساب .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 63', 'لا تنفذ الأحكام الصادرة بفسخ عقود الزواج أو بطلانها أو بالطلاق أو التطليق إلا بانقضاء مواعيد الطعن عليها طريق النقض فإذا طعن عليها فى الميعاد القانونى استمر عدم تنفيذها الى حين الفصل فى الطعن وعلى رئيس المحكمة أو من ينيبه تحديد جلسة لنظر الطعن مباشرة أمام المحكمة فى موعد لا يجاوز ستين يوما من تاريخ ايداع صحيفة الطعن قلم كتاب المحكمة أو وصولها اليه وعلى النيابة العامة تقديم مذكرة برايها خلال ثلاثين يوما على الأكثر قبل الجلسة المحددة بنظر الطعن وإذا نقضت المحكمة الحكم كان عليها أن تفصل فى الموضوع .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 64', 'لا يجوز التماس اعادة النظر فى مسائل الولاية على المال إلا فى القرارات الانتهائ الصادرة فى المواد الاتية :
توقيع الحجر أو تقرير المساعدة القضائية أو اثبات الغيبة .
تثبيت الوصى المختار أو الوكيل عن الغائب .
عزل الوصى والقيم والوكيل أو الحد من سلطتة .
سلب الولاية أووقفها أو الحد منها .
استمرار الولاية أو الوصاية على القاصر .
الفصل فى الحساب .
الباب الخامس
فى تنفيذ الأحكام والقرارات', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 65', 'الأحكام والقرارات الصادرة بتسليم الصغير أو رؤيتة بالنقفات أو الأجور أو المصروفات وما فى حكمها تكون واجبة النفاذ وبقوة القانون وبلا كفالة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 66', 'يجوز تنفيذ الأحكام والقرارات الصادرة بضم الصغير وحفظو وتسليمه جبرا ويتبع فى تنفيذ الأحكام الصادرة فى هذا الشأن ما ينص عليه القانون من اجراءات ويراعى فى جميع الأحوال أن تتم اجراءلات التنفيذ ودخول المنازل وفقا لما يأمر به قاضى التنفيذ ويجوز اعادة التنفيذ بذات السند التنفيذى كلما اقتضى الحال ذلك .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 67', 'ينفذ الحكم الصادر برؤية الصغير فى أحد الأماكن التى يصدر بتحديدها قرار من وزير العدل بعد موافقة وزير الشون الاجتماعية وذلك ما لم يتفق الحاضن وزالصادر لصالحة الحكم على مكان اخر ويشترط فى جميع الأحوال ما يشيع الطمانينة فى نفس الصغير .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 68', 'علىىقلم كتاب المحكمة التىىأصدرت الحكم أو القرار بوضع الصيغة التنفيذية عليه اذا كان واجب النفاذ .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 69', 'يجب التنفيذ بمعرفة المحضرين أو جهة الادارة ويصدر وزير العدل قرارا باجراءات تنفيذ الأحكام والقارات الصادرة بتسليم الصغير أو ضمه أو رؤته أو سكناه ومن يناط به ذلك .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 70', 'يجوز للنيابة العامة متى عرضت عليها منازعة بشأن حضانة الصغير فى سن حضانة النساء أو طلبت حضانته مؤقتا من يرجح الحكم لها بذلك بعد أن تصدر بعد اجراء التحقيق المناسب قرارا مسببا لتسليم الصغير الى من تحقق مصلحته معها ويصدر القرار من رئيس نيابة على الأقل ويكون واجب التنفيذ فورا الى حين صدور حكم من المحكمة المختصة فى موضوع حضانة الصغير .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 71', 'ينشاء نظام لتأمين الأسرة من بين أهدافة ضمان تنفيذ الأحكام الصادرة بتقرير نفقة للزوجة أو المطلقة أو الأولاد أو الأقارب يتولى الإشراف على تنفيذى بنك ناصر الاجتماعىويصدر بقواعد هذا النظام واجراءاته وطرق تمويله قرار من وزير العدل بعد موافقة وزيرة التأمينات .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 72', 'على بنك ناصر الاجتماعى أداء النفقات والأجور وما فى حكمها بما يحكم به للزوجة أو المطلقة أو الأولاد أو الوالدين وذلك وفقا للقواعد والاجراءات التى يصدر بها قرار من وزير العدل بعد موافقة وزيرة التأمين .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 73', 'على الوزارات والمصالح الحكومية ووحدات الادارة المحلية والهيئات العامة ووحدات القطاع العام وقطاع الأعمال العام وجهات القطاع الخاص والهيئة القومية للتأمين الاجتماعى وادارة التأمين والمعهاشات للقوات المسلحة والنقابات المهنية وغيرها من جهات اخرى بناء على طلب من بنك ناصر الاجتماعى مرفق به صوره طبق الأصل من الصورة التنفيذية للحكم وبما يفيد تمام الإعلان أن تقوم بخصم المبالغ فى الحدود التى يجوز الحجر عليها وفقا للمادة 76 من هذا القانون من المرتبات وما فى حكمها والمعاشات وإيداعها خزانة البنك فور وصول الطلب اليها ودون حاجة الى اجراء اخر .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 74', 'اذا كان المحكوم عليه من غير ذوى المرتبات أو الأجور أو المعاشات وما فى حكمها وجب عليه أن يودع المبلغ المحكوم بع خزانة بنك ناصر الاجتماعى أو أحد فروعه أو وحدة الشئون الاجتماعية الذى يقع محل اقامته فى دائرة أيا منهم فى السبوع الول من كل شهر متى قام البنك بالتنبيه عليه بالوفاه .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 75', 'لبنك ناصر الاجتماعى استيفاء ما قام بأداءه من نفقات وأجور وما فى حكمها وجميع ما تكبده من مصاريف فعلية أنفقها بسبب امتناع المحوم عليه عن أداءه .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 76', 'استثناء ما تقررة القوانين فى شأن قواعد الحجر على المرتبات أو الأجور أو المعاشات وما فى حكمها يكون الحد الأقصى لما يجوز الحجر عليه منها وفاء لدين نفقة أو اجر أو مافى حكمها للزوجة أو للمطلقة أو الأولاد أو الوالدين فى حدود النسبة الاتية :
25 % للزوجة أو المطلقة وتكون 40 % فى حالة أكثر من واحدة .
25 % للوالدين أو أحدهما .
35 % للولدين أو أقل .
40 % للزوجة أو المطلقة ولولد أو اثنين والوالدين أو أيهما .
50 % للزوجة أو المطلقة وأكثر من ولدين والوادين أو أيهما وفى جميع الأحوال لا يجوز أن تزيد النسبة التى لا يجوز الحجر عليها على 50 % تقسم بين المستحقين بنسبة ما حكم به لكل منهم .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 76', 'مكرراً :
اذا امتنع المحكوم عليه عن تنفيذ الحكم النهائى الصادر فى دعاوى النفقات والأجور وما فى حكمها جاز للمحكوم له أن يرفع الأمر الى المحكمة التى اصدرت الحكم أو التى يجرى التنفيذ بدائرتها ، ومتى ثبت لديها أن المحكوم عليه قادر على القيام بأداء ما حكم به وأمارته بالأداء ولم يمتثل حكمت بحبسة مدة لا تزيد عن ثلاثين يوما .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 77', 'فى حالة التزاحم بين الديون تكون الأولوية لدين نفقة الزوجة أو المطلقة فنفقة الأولاد فنفقة الوالدين فنفقة الأقارب ثم الديون الاخرى .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 78', 'لا يترتب على الأشكال فى تنفيذ أحكام النفقة المشار اليها فى المادة السابقة بوقف اجراءات التنفيذ .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 79', 'مع عدم الاخلال باى عقوبة أشد ينص عليها قانون العقوبات أو أى قانون اخر يعاقب بالحبس الذى لا تقل مدتة عن ستة أشهر كل من توصل الى الحصول على أى مبالغ من بنك ناصر الاجتماع نفاذا لحكم أو لأمر صدر استنادا الى أحكام هذا القانون بناء على اجراءات أو أدلة صورية أوو
 مصطنعة ما علمه بذلك وتكون العقوبة الحبس الذى لا تزيد متدة على سنتين لكل من تحصل من بنك ناصر الاجتماعى على مبالغ غير مستحقة له مع علمه بذلك مع الزامة بردها .
قرارات وزير العدل الخاصة
بالأحوال الشخصية والولاية على النفس
واجراءات التقاضى

قرار وزير العدل رقم 3269 لسنة 1985 بشأن أوضاع واجراءات اعلان وتسليم اشهاد الطلاق الى المطلقة واخطار الزوجة بالزواج الجديد تنفيزا للمرسوم بالقانون رقم 25 لسنة1929 الخاص ببعض أحكام الأحوال الشخصية المعدل بالقانون رقم 100 لسنة 1985 بتعديل بعض أحكام قوانين الأحوال الشخصية .
وزير العدل :
يعد افطلاع على المرسوم بقانون رقم 25 لسنة 1929 الخاص ببعض أحكام الأحوال الشخصية المعدل بالقانون رقم 100 لسنة 1985 بتعديل بعض أحكام القوانين الأحوال الشخصية .
وعلى المادة 381 من المرسوم بقانون رقم 78 لسنة 1921 بشأن لائحة ترتيب المحاكم الشرعية والاجراءات المتعلقة بها .
وعلى القانون رقم 68 لسنة 1947 بشأن التوثيق ولائحتة التنفيذية وعلى قانون المرفعات المدنية والتجارية الصادر بالقانون رقم 13 لسنة 1968 .
وعلى لائحة الماذونين الصادرة بقرار وزير العدل المؤرخ 4 يناير لسنة 1955 .
وعلى لائحة الموثقين المنتدبين الصادر بقرار وزير العدل المؤرخ 26 ديسمبر سنة 1955 .
قـــرار', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 1', 'على الموثق المختص بتوثيق اشهاد الطلاق أن يثبت فيه بيانا واضحا عن محل اقامة المطلقة ويكون اثبات هذا البيان بإرشادها فى حالة حضورها توثيق افشهاد وبإرشاد المطلق فى حالة عدم حضورها .
ويجب على الموثق المختص فى جميع الأحوال اثبات محل اقامة المطلق فى إشهاد الطلاق .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 2', 'يجب على الموثق خلال سبعة أيام من تاريخ توثيق اشهاد الطلاق اعلان المطلقة لشخصها على يد محضر بوقوع اطلاق وذلك فى حالة عدم حضورها توثيق اشهاده .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 3', 'يجب أن يتضمن الإعلان المشار اليه في المادة الساببقة البيانات الاتية :
تايخ وقوع الطلاق .
اسم الموثق الذىوثق اشهاد الطلاق ومقرعمله .
 رقم اشهاد الطلاق ز
بيان الطلاق الذى تضمنه الاشهاد .
اختار المطلقة باستلام نسخة اشهاد الطلاق الخاصة بها من الموثق المختص خلال خمسة عشرة يوما من تاريخ الاعلان .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 4', 'فيما عدا ما تقدم تطبق القواعد والاجراءات المقررة فى قانون المرافعات والمدنية والتجارية على الإعلان بوقوع الطلاق .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 5', 'على الموثق تسليم المطلقة أو من ينيب عنها نسخة اشهاد الطلاق الخاصة بها بعد أخذ ايصال بذلك يرفق باصل الإشهاد فإذا لم تحضر المطلقة أو نائبها لدي الموثق لاستلام نسخة الاشهاد الخاصة', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 4', 'فيما عدا ما تقدم تطبق القواعد والاجراءات المقررة في قانون المرافعات المدنية والتجارية علي الاعلان بوقوع الطلاق', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 5', 'علي الموثق تسليم المطلقة او من تنيبه عنها نسخة اشهاد الطلاق الخاصة بها بعد اخذ ايصال بذلك يرفق باصل الاشهاد , فاذا لم تحضر المطلقة او نائبها لدى الموثق لاستلام نسخة الاشهاد الخاصة بها يجب علي الموثق تسليم هذه النسخة الى المحكمة التابع لها بعد انقضاء ثلاثين يوما من تاريخ التوثيق بمقتضى ايصال يفيد ذلك وعلى المحكمة في هذه الحالة ارسالها الي المطلقة بكتاب مسجل بعلم الوصول ان كانت تقيم في مصر او بواسطة وزارة الخارجية ان كانت تقيم في الخارج .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 6', 'علي الموظف المختص بالمحكمة قيد نسخة اشهادات اللاق التي تسلم اليه فور استلامها في سجل خاص يبين فيه رقم الاشهاد وتاريخ واسم الموثق واسم المطلقة ومحل اقامة كل منهما وبيان الطلاق الوارد بالاشهاد وتاريخ استلامه نسخة الاشهاد بالمطلقة وعلية ارسالها في اليوم التالي لاستلامها الي المطلقة وفقا لاحكام المادة السابقة مع اثبات تاريخ ورقم الارسال في السجل المشار اليه , والتاشير فيه بعد ذلك بما تم نو تسليم النسخة الي المطلقة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 7', 'اذا اعيدت نسخة الاشهاد الخاصة بالمطلقة الي النحكمة بعد ارسالها اليها لتعذر تسليمها , فعلي الموظف المختص بالمحكمة حفظها في ملف خاص والتاشير بذلك في السجل المشار اليه في المادة السابقة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 8', 'علي الموثق المختص بتوثيق وثيقة الزواج ان يثبت في الوثيقة بيانا واضحا عن حالة الزوج الاجتماعية فاذا كان متزوجا فيجب ان يتضمن هذا البيان اسم الزوجة او الزوجات اللاتى في عصمة الزوج ومحال اقامتهن هذا البيان من واقع اقرار الزوج .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 9', 'على الموثق اخطار الزوج او الزوجات اللاتى في عصمة الزوج بالزواج الجديد خلال سبعة ايام من تاريخ توثيق الزواج وذلك بكتاب مسجل مقرون بعلم الوصول ان كانت الزوجة تقيم في مصر او بالطريق الذى رسمة قانون المرافعات المدنية والتجارية ان كانت تقيم في الخارج .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 10', 'يلغى قرار وزي العدل رقم 2445 لسنة 1979 كما يلغى كل نص يخالف احكام هذا القرار .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 11', 'ينشر هذا القرار في الوقائع المصرية .
صدر في 17 / 7 / 1985 
 وزير العدل
 المستشار / احمد ممدوح عطية

وزارة العدل
قرار وزير العدل رقم 1086 لسنة 2000
بالمعاونيين الملحقيين للعمل بنيابات
الأحوال الشخصية ومنحهم صفة الضبطية
القضائية
وزير العدل 
بعد الاطلاع علي قانون تنظيم بعض أوضاع وإجراءات التقاضى في مسائل الاحوال الشخصية الصادر بالقانون رقم 1 لسنة 2000 
قرر', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 1', 'يكون للمعاونين العاملين حاليا بيانات الاحوال الشخصية صفة الضبطية القضائية في خصوص الاعمال التى تناط بهم أثناء تأديتهم الأعمال وظائفهم , وذلك فيما يتعلق بتطبيق حكم المادة 26 من القانون رقم 1 لسنة 2000 .
كما تثبيت تلك الصفة لكل من يعين بهذه الوظيفة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 2', 'ينشر هذا القانون في القرار الوقائع المصرية , ويعمل به من اليوم التالى لتاريخ نشرة .
صدر في 6 / 3 / 2000 .
 وزير العدل
 المستشار / فاروق سيف النصر
وزارة العدل
قرار وزير العدل رقم 1087 لسنة 2000
بتحديد أماكن تنفيذ الإحكام الصادرة
براية الصغير والإجراءات الخاصة بتنفيذ
الأحكام والقرارات الصادرة بتسليم الصغير
او ضمه او رؤيته او سكناه ومن يناط به ذلك
وزير العدل 
بعد الاطلاع علي قانون تنظيم بعض الأوضاع وإجراءات التقاضى في مسائل الأحوال الشخصية الصادر بالقانون رقم 1 لسنة 2000 وبناء علي موافقة وزيرة التأمينات والشئون الاجتماعية 
قــرر', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 1', 'تنفذ الاحكام والقرارات الصادرة بتسليم الضغير او ضمة او رؤيته او سكناه تطبيقا لاحكام المادتين 67 , 69 من القانون رقم 1 لسنة 2000 بمراعاة القواعد والاجراءات المبينه في المواد التالية .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 2', 'يجرى تنقيذ الاحكام والقرارات الصادرة بتسليم الصغير او ضمة او سكناه بمعرفة المحضر المختص وبحضور احد الاخصائين الاجتماعين الملحقين للمحكمة , فان حدثت مقاومة او امتناع وعدم استجابة للنصح والارشاد - برفع الامر لقاضى التنفيذ ليامر بالتنفيذ والاستعانة بجهة الادارة بالقوة الجبرية ان لزم الامر , ويحرر الاخصائى الاجتماعي مذكرة تتضمن ملاحظاته ترفق باوراق التنفيذ .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 3', 'يراعي في جميع الاحوال ان تتم اجراءات التنفيذ ودخول المنازل وفقا لما يامر به قاضى التنفيذ , ويجوز اعادة التنفيذ بذات السند التنفيذى كلما اقتضى الحال ذلك علي النحو المبين في المادة 66 من القانون رقم 1 لسنة 2000 .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 4', 'في حالة عدم اتفاق الحاضن او من بيده الصغير والصادر لصاله الحكم علي المكان الذى يتم فيه رؤية الصغير , ويكون للمحكمة ان تنتقى من الاماكن التالية مكانا للرؤية وفقا للحالة المعروضة عليها وبما يتناسب - قدر الاماكن - وظروف اطراف الخصومة , مع مراعاة ان يتوفر في المكان ما يشيع الطمانينة في نفس الصغير ولا يكبد اطراف الخصومة مشقة لا تحتمل :
احد النوادى الرياضية والاجتماعية .
احد مراكز رعاية الشباب .
احدى دور رعاية الامومة والطفوله التى يتوافر فيها حدائق .
احدى الحدائق العامة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 5', 'يجب ان لا تقل مدة الرؤية عن ثلاث ساعات اسبوعيا فيما بين السعة التاسة صباحا والساعة السابعة مساءا . ويراعى قدر الامكان ان يكون ذلك خلال العطلات الرسمية وبما لا يتعارض ومواعيد انتظام الصغير في دور التعليم .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 6', 'ينفذ الحكم الصادر برؤية الصغير في المكان والزمان المبين بالحكم .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 7', 'لاى طرف من اطراف السند التنفيذى ان يستعين بالاخصائى الاجتماعى المنتدب للعمل بدائراة المحكمة التي اصدرت حكم الرؤية لاثبات نكول الطرف الاخر عن التنفيذ في المواعيد والاماكن المحددة بالحجم , ويرفع الاخصائى الاجتماعى تقريرا للمحكمة بذلك اذا ما اقام الطالب دعوى في هذا الخصوص .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 8', 'ياتزم المسئول الادارى بالنوادى الرياضية او الاجتماعية او بمراكز رعاية الشباب او بدور رعاية الطفوله والامومة التى يجرى تنفيذ حكم الرؤية فيها , وبناء علي طلب اى من اطراف السند التنفيذى , ان يثبت في مذكرة يحررهاحضور او عدم حضور المسئول عن تنفيذ حكم الرؤية وبيدة الصغير .
ولمن حررت المذكرة بناء علي طلبه ان يثبت مضمونها في محضر يحرر في قسم او مركز الشرطة التابع له مكان التنفيذ .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 9', 'ينشر هذا القرار في الوقائع المصرية , ويعمل من اليوم التالي لتاريخ نشره .
صدر في 6 / 3 / 2000 
وزير العدل 
المستشار / فاروق سيف الدين 
وزارة العدل
قرار وزير العدل رقم 1088 لسنة
2000 بالاجراءات التي تتخذها النيابة العامة
في شان جرد اموال المعنين بالحماية
وزير العدل
بعد الاطلاع على قانون تنظيم بعض اوضاع واجراءات التقاضى في مسائل الاحوال الشخصية الصادر بالقانون رقم 1 لسنة 2000 :
قــرر', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 1', 'تتبع الاجراءات المبينة في المواد التالية في شان جرد اموال المعينيين باحماية وفقا لحكم المادة 41 من القانون رقم 1 لسنة 2000 .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 2', 'تخطر النيابة العامة من صدر في غيبته قرارا من المحكمة بتعيينه وصى او قيم او وكيل عن الغائب او مساعد قضائى او مدير مؤقت بالقرار الصادر , وذلك لشخصية علي يد محضر , فان اعترض خلال الميعاد المنصوص عليه في المادة 40 من القانون رقم 1 لسنة 2000 المشار اليه وجب اتباع حكم المادة 39 من ذلك القانون .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 3', 'تخطر النيابة العامة النائب المعين وذوى الشان بالموعد الذى حددته لجرد اموال المعنى بالحماية , وذلك بموجب اعلان علي يد محضر , وللنيابة العامة دعوة القاصر الذى اتم خمس عشرة سنة ميلادية الحضور اجراءات الجرد متى رات ضرورة لحضوره .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 4', 'تتولى النيابة العامة بنفسها او بمن تندبه لذلك من المعاونين الملحقين بها مباشرة اجراءات الجرد .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 5', 'تثبت الاجراءات التى تتخذ التى في شان جرد اموال المعنى بالحماية في محضر من نسختين يشار فيه لتاريخ افتتاح المحضر ومكانه وشخص القائم به , واثبات دعوى ذوى الشان والنائب المعين لحضور الجرد واثبات - حضور من حضر منهم واقواله ان رغب في الادالاء باقوال تتعلق بما سيتم جرده من اموال وحقوق وديون .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 6', 'تثبت حالة الاختام التى امرت النيابة العامة بوضعها عند حصر الاموال اعمالا للمادة 33 من القانون رقم 1 لسنة 2000 المشار اليه , بعد التاكد من سلامتها يتم رفعها , ويطابق ما سبق حصره من اموال علي الواقع .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 7', 'يتم جرد جميع الاموال والمنقولات مع بيان اوصافها وتقدير قيمتها , وللنيابة العامة ان تستعين في ذلك باهل الخبرة من المختصين , وفي هذه الحالة يثبت في المحضر اسم وعمل من قام بهذا التقدير , فان تعذر الاستعانه باهل الخبرة وقت الجرد , كان للنيابة العامة ان تتحفظ مؤقتا على ما لم تقدر قيمته من الاموال او تعين عليها حارسا ان لزم الامر لحين عرضها علي خبير لتقدير قيمتها , علي ان يثبت في المحضر اوصاف ما تم التحفظ عليه .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 8', 'وان كان من بين اموال المعنى بالحماية معادن او احجار ثمينة او حلى . يجب بيان نوعها ووزنها وعيارها , وذلك بمعرفة اهل الخبرة , فان تعذر ذلك وقت الجرد اتبع حكم المادة السابقة . مادة 9 : 
يرفق بمحضر الجرد مذكرة منالخبير تتضمن - بحسب الاحوال - نوع واوصاف واوزان زاعيار الاشياء والاموال التى عهد بها اليه وقيمة كل منها , ويثبت مضمون ما اشتملت عليه المذكرة في المحضر .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 10', 'يتم اثبات ما يوجد من النقود السائلة مع بيان نوعها ومقدراها .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 11', 'يتم اثبات ما يوجد من الاسهم والسندات , وترقم اوراقها ويؤشر علي كل منها من القائم بالجرد .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 12', 'تثبت حالة الدفاتر والسجلات التجارية , وترقم صحائفها ويوشر علي ما لم يسبق التاشير عليه من قبل اثناء حصر الاموال , وتملا الفرغات بوضع علامات خطيه .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 13', 'للنيابة العامة ان تستعين بخبير حسابى لفحص الدفاتر والسجلات التجارية والسندات توصلا الى ما للمعنى بالحماية من اموال وحقوق وما علية من التزامات مالية .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 14', 'تثبت حالة الخزان المعلقة ان وجدت , وبعد فتحها يتم جرد ما بها من اموال ومستندات وغيرهم .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 15', 'اذا تبين اثناء الجرد وجود وصية مفتوحة تعين اثبات حالتها ومضمونها بالمحضر بعد التاشير عليها من القائم باعمال الجرد .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 16', 'اذا تبين اثناء الجرد وجود وصية او اوراق اخرى مختومة يتم اثبات ما يوجد علي ظاهرها من كتابة او ختم , والتوقيع علي المظروف الذى يحتويها من القائم باعمال الجرد والحاضر من ذوى الشان والنائب المعين , وتحديد اليو الذى يتم فض المظروف فيه بمعرفة النيابة العامة واعلان الحاضرين بذلك , وفي اليوم المحدد تتولى النيابة العامة فض الاحراز واثبات حالة ما يوجد بها من اوراق وغيرها , وتامر بعرضها علي المحكمة المختصة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 17', 'اذا تبين للنيابة العامة من ظاهر ما هو مكتوب علي الاحراز المختومة انها مملوكة لغير ذوى الشان , تعين عليها استدعاؤها في ميعاد تحدده لحضور فض الاحراز , وفي اليوم المحدد تتولى النيابة العامة فضها ولو لم يحضر من تم استدعاؤهم و فان تبين ان الاحراز لا شان لها بالمعنى بالحماية تسلمها لذوى الشان او تعيد تحريزها لتسلم اليهم عند طلبها . فاذا ثار نزاع في هذا الشان تعين عرض امره علي المحكمة المختصة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 18', 'يثبت في محضر بيان ما سبق نقله الي احد المصارف او الى اى مكان اخر من الاموال والاوراق المالية والمستندات والمصوغات اعمالا للفقرة الثانية من المادة 33 من القانون رقم 1 لسنة 200 المشار اليه , ويتم حصر وتقييم هذه الاموال والمستندات وغيرها بمراعاة القواعد المتقدمة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 19', 'في حالة وجود نزاع علي اى من الاموال او الاشياء التى تم جردها تعين عرض الامر بشانها علي المحكمة المختصة بعد اتخاذ الاجراءات التحفظية او المؤقته المناسبة ز', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 20', 'ان تعذر اتمام اجراءات الجرد في يوم افتتاح المحضر تعين اثبات ما تم من اجراءات في حينه وارجاء الاعمال الاخرى ليوم تال يحدد ويوقع علي المحضر من النائب المعين والحاضر من ذوى الشان والقائم باعمال الجرد , ويعد توقيعهم بمثابة اخطار لهم باليوم المحدد لاستكمال اعمال الجرد .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 21', 'بعد اتمام اعمال الجرد تسلم الاموال للنائب المعين ويوقع ذوو الشان والقائم باعمال الجرد والنائب المعين علي المحضر ويعد النائب المعين مسئولا عن الاوال التى تسلمها من تاريخ توقيعه . وترفع النياب العامة محضر الجرد الى المحكمة للتصديق عليه علي النحو المبين بالمادة 42 من القانون رقم 1 لسنة 2000 المشار اليه .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 22', 'في حالة مصف لتركة قبل تعيين النائب عن المعنى بالحماية ومباشرة النيابة العامة لاجراءات الجرد يتبع حكم المادة 45 / 1 من القانون رقم 1 لسنة 2000 في شان هذه الاجراءات .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 23', 'ينشر هذا القرار في الوقائع المصرية , ويعمل به من اليوم لتاريخ نشره . صدر في 6 / 3 / 2000 
 وزير العدل
 المستشار / فاروق سيف النصر
 
وزارة العدل
قرار وزير العدل رقم 1089 لسنة 2000
بقواعد وإجراءات أعمال الأخصائيين
الاجتماعيين الملحقين بالمحاكم الابتدائية 
وزير العدل 
بعد الاطلاع على قانون تنظيم بعض اوضاع واجراءات التقاضى في مسائل الاحوال الشخصية الصادر رقم 1 لسنة 2000 : وبناء علي موافقة وزيرة التامينات والشئون الاجتماعية .
قــرر', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 1', 'ينشا بمقر كل محكمة مكتب للاخصائين الاجتماعيين يخضع للاشراف المباشر لرئيسها .
ولرئيس المحكمة الابيتدائية انشاء مكاتب فرعية بمقار المحاكم الجزئية التابعة له ويسند الاشراف على اعمالها لقاضى المحكمة الجزئية .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 2', 'يعد سجل بكل محكمة انشء بمقرها مكتب لاخصائين الاجتماعيين لقيد الماموريات التي تعهد بها المحكمة لهم .
وتقيد المامورية في السجل بارقام مسلسة مع بداية كل عام قضائى . وتتضمن بيانات السجل ما يلى : 
رقم الدعوى . اسماء المدعين عليهم زمحال اقامتهم , تاريخ قرار المحكمة , وملخص لمضمون القرار , اسم الاخصائى الاجتماعى المنتدب , تاريخ استلام المامورية وتوقيعه بالاستلام ,وتاريخ ايداع التقرير وعدد اوراقة وتوقيع مقدمه .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 3', 'يقوم رئيس المحكمة الابتدائية او من يعهد اليه من قضاتها بمراجعة القيد في السجل المبين بالمادة السابقة شهريا .
للوقوف على حسن سير العمل بمكتب الاخصائيين الاجتماعيين , ووضع القواعد اللازمة لضبط العمل به . 
ولرئيس المحكمة الابتدائية - عند اللزوم - ان يرفع مذكرة مسببة لوزير العدل باقتراح رفع اسم من يثبت عدم صلاحيته لاداء العمل من الاخصائيين الاجتماعيين .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 4', 'يعهد الى كل من المبينة اسماؤهم باكشوف المرافقة لقرار وزير العدل باصدار قوائم الاخصائيين الاجتماعيين بالعمل كاخصائيين اجتماعيين بدوائر المحاكم الابتدائية المبينة فريق اسم كل منهم .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 5', 'تعهد المحكمة بامامورية للاخصائى الاجتماعى حسب دوره في الترتيب الوارد بالكشف الخاص بها , وللمحكمة ان تعهد بالمامورية لاخصائى بعينة دون التزام بهذا الترتيب اذا رات ذلك لاسباب تقدرها .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 6', 'يتعين على الاخصائى الاجتماعى التواجد بالمككتب المشار اليه في المادة الاولى من هذا القرار خلال الايام التى يحددها رئيس المحكمة الابتدائية , وبصفة خاصة في الايام التى تنظر خلالها جلسات الاحوال الشخصية واليوم التالى لها , لاستلام الاخطارات الخاصة بالماموريات التي تامر بها المحكمة . علي ان يكون التواجد بمقار المحاكم الجزئية خلال تلك الايام لاستلام اخطارات الماموريات او ايداع التقارير بحسب الاحوال .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 7', 'يجب على امين سير الدائرة اثبات اسم الاخصائى الاجتماعى الذى عهد اليه بمامورية على غلاف ملف الدعوى , ويوقع الاخصائى الاجتماعى فى السجل المبين في المادة الثانية من هذا القرار بما يفيد اطلاعه على ملف الدعوى وتاريخ ذلك .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 8', 'يجب على الاخصائى الاجتماعى المبادرة بمباشرة المامورية المكلف بها فور توقيعيعة علي السجل المبين بالمادة الثانية من هذا القرار , وان يودع تقريره عنها في موعد غايته عشرة ايام .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 9', 'علي الاخصائى الاجتماعى ان يثبت في تقريره ىكافة الاجراءات التى اتخذها في سبيل مباشرة المامورية , وملخص للحالة او المسالة المعروضة علية , وكافة ما تكشف له من خلال البحث , وخاصة ما يتعلق بالامور الاتية : 
رقم الدعوى واسماء اطراف الخصومة ورقم قيد المامورية في السجل وتاريخ استلامه لها .
الحالة الاجتماعية لاطراف الخصومة . وجنسياتهم وديانتهم وعمل كل منهم .
الحالة الاقتصادية لاطراف الخصومة . 
المستوى الثقافى والعلمى لاطراف الخصومة .
 بحث الحالة من حيث محل الاقامة واوصافة والمستوى المعيشى والبيئة المحيطة . 
بحث المستوى الثقافى والعلمى لابناى اطراف التراع , ودور التعليم الملحقين بها والصف الدراسى ومستوى التحصيل , وذلك من خلال الرجوع الى المختصين بها وعن طريق الحديث المباشر دون توجيه مكاتبات في هذا الخصوص . 
 ان كان الابناء ملتحقين بعمل يجب ا يثبت في التقرير نوع هذا العمل وطبيعته وما اذا كانت حالتهم الصحية والعقلية من حيث المبدا تتفق وطبيعة العمل من عدمه والدوافع لالتحاق الابناء بهذه الاعمال . 
 ان كان احد افراد الخصومة مريضا بمرض مزمن او عاهة جسدية او عقلية تعين على الاخصائى اثبات ذلك في تقريره , وما اذا كان يتلقى علاجا من عدمة . 
وعلى الأخصائى ان يضمن تقريره كافة ما يتيح للمحكمة الوقوف على الواقع الفعلى لحياة أطراف الخصومة وابنائهم .وان يدعم ذلك بالمستندات المؤدية قدر الإمكان بما فى ذلك التصوير الفوتوغرافى للمسكن بعد الحصول على اذن المقيمين به - والمنطقة التى يقع بها , وكافة ما يعبر بصدق عن الواقع الفعلى .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 10', 'يحرر التقرر من نسختين متطابقتين , وتوقع جميع اوراقة من الاخصائى الاجتماعى ويثبت فيه تاريخ انتهاء المامورية وتاريخ ايداع التقرير مع مراعاة الاتى : 
تسلم نسخة من التقرير لقلم كتاب المحكمة وبمعرفة الاخصائى القائم بالمامورية ويوقع على السجل المبين بالمادة الثانية من هذا القرار بما يفيد ايداعه التقرير كما على ملف الدعوى الصادر فيها المامورية بما يفيد ذلك الايداع وعدد اوراق التقرير المودع منه . 
يقوم امين سر الدائرة بعد مطابقة نسخة التقرير المودعة على النسخة الاخرى بالتوقيع علي كافة اوراقها ويعيدها للاخصائى الاجتماعى لايداعها سجل المكتب المبين بالمادة الاولى . 
يقوم رئيس قلم كتاب محكمة الاحوال الشخصية المختص بالقيد في السجل المبين بالمادة الثانية من هذا القرار و بختم اوراق نسخة التقرير , وتحفظ بالمكتب بعد ادراجها ضمن كشوف مسلسلة للرجوع اليها عند الضرورة .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 11', 'لوزير العدل ان يضم اخصائين اجتماعيين للعمل بدوائر المحاكم الابتدائية بعد موافقة وزيرة التامينالت الاجتماعية . وله ان يرفع اسم اى اخصائى اجتماعى من القوائم الخاصة بكل محكمة مع اخطار جهة عملة بذلك , وان ينقل ايا منهم للعمل بدوائر محاكم ابتدائية اخرى لمصلحة العمل .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 12', 'ينشر هذا القرار في الوقائع المصرية , ويعمل به من غاليوم التالى لتاريخ نشره . 
صدر في 6 / 3 / 2000 
وزير العدل
المستشار / فاروق سيف النصر

وزارة العدل
قرار وزير العدل رقم 1090 لسنة 2000
باجراءات القيد والشطب في السجل
الخاص بمواد الولاية علي المال
وزير العدل بعد الاطلاع على قانون تنظيم بعض اوضاع واجراءات التقاضى في مسائل الاحوال الشخصية الصادر بالقانون رقم 1 لسنة 2000 . 
قــرر', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 1', 'ينشا في كل نيابة كلية سجلا لقيد الطلبات المتعلقة بمسائل الولاية والوصاية والحجر والغيبة والمساعدة القضائية تنفيذا لحكم المادة 32 من القانون رقم 1 لسنة 2000 , وتتبع والاجراءات المنصوص عليها في هذا القرار في شان القيد والشطب في هذا السجل .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 2', 'يتم القيد في السجل المشار اليه المادة السابقة , علي النحو التالى : 
اولا : تقيد الطلبات بارقام متسلسة تبدا فى بداية كل عام قضائى , وتنتهى بنهايته . 
على ان تقيد الطلبات الخاصة بعام 2000 اعتبار من 15 / 3 / 2000 الى 31 / 9 / 2000 . 
ثانيا : يقيد كل طلب في صفحة مستقلة , وفقا لما هو مبيينا بالنموذج المرفق بالقرار . وتمهر صفحات السجل بخاتم النيابة . 
ثالثا : يتم اثبات قيد الطلب فور تقديمة بمعرفة رئيس قلم الاحوال الشخصية او من يقوم مقامة , ويعتمد القيد من رئيس النيابة الكلية في موعد اقصاه اليوم التالى لتاريخ القيد . 
رابعا : يتم اثبات تاريخ القيد وساعته واسم الطالب وموطنه بعد التاكد من شخصيته , واثبات صفته بالنسبة للمقدم ضده الطلب . وبيان سند وكالته الذى يخوله الحق في تقديم الطلب , وتثبت بيانات التوكيل بالسجل , ويرفق التوكيل بملف الطلب ان كانت بيانات التوكيل بالسجل ويرفق التوكيل بملف الطلب ان كانت الوكالة عامة وفى جميع الأحوال يجب أن يوقع مقدم منه إن كانت الوكالة عامة وفى جميع الأحوال يجب أن يوقع مقدم الطلب قرين تلك البيانات فى الموضوع المعد لذلك بالسجل .
خامسا : بيان اسم المقدم ضده الطلب وسنة وموطنه وديانته وجنسيته .
سادسا : يثبت ملخص لموضوع الطلب فى الموضع المعد لذلك بالسجل .
سابعا : يثبت منطوق القرارات الصادرة من النيابة العامة وما اتذته فى شأن أى الاجراءات التالية ، مع بيان اسم وصفة القائم بها وتاريخ اتخاذها وتوقيعه قرين ذلك :
اجراءات حصر أموال وحقوق المعنى بالحماية 
اجراءات وضع الأختام ورعها .
رقم الأمر الصادر بالترخيص للنيابة العامة فى نقل الأموال والأوراق الالية والمستندات والمصوغات وغيرها مما يخشى علية الى خزانة احد المصارفى أو الى ألى أى مكان أمين .
بيان الجهة التى أودعت لديها تلك الأشياء وتاريخ ايداعها ورقم الإيداع .
أى قرارات اخرى تأمر بها النيابة العامة .
ثامنا : يثبت تايخ ومنطوق القرار الصادر بتعيين النائب عن المعنى بالحماية واسمه وموطنه وتاريخ اخطاره بقرار تعيينه ان صدر فى غيبته كما يبت تاريخ اعتراضه على هذا التعيين فى حالة اعتراضه وتاريخ صدور القرار الصادر بتعيين اخر بدلا منه وتتبع فى شأنه الاجراءات السابقة .
تاسعا : يثبت تاريخ الاجراءات التى اتبعتها النيابة العامة فى شأن جرد أموال المعنى بالحماية بعد تعيين النائب عنه وشخص القائم بالجرد واسم عضو النيابة الذى وقع على محضر الجرد .
كما تثبت كافة القرارات المتعلقة بندب أهل الخبرة لتقييم الأموال والديون .
عاشرا : يثبت تاريخ تسليم الأموال التى تم جردها للنائب المعين بعد اثبات اسمه وموطنه وتوقيعه على ما يفيد ذلك فى الموضع المخصص بالسجل .
حادىعشر : يثبت تاريخ تعيين مصفى على التركة ورقم الدعوى الصادر فيها قرار تعيينه واسم المصفى وموطنه وتاريخ استلامه لأموال التركة والريخ الانتهاء من أعمال التصفية .
ثانى عشر : تثبت كافة القرارات الاخرى التى تصدرها المحكمة فى خصوص ادارة أموال المعنى بالحماية .
ثالث عشر : تثبت كافة القرارات التى تصدرها محكمة ثانى درجة فى خصوص مواد الولاية على المال وتاريخ صدورها .
رابع عشر : يثبت تاريخ القرار النهائى الصادر بشطب الطلب وويدون فى السجل عبارة " شطب القيد " ورقم المادة الصادر فيها ذلك القرار .
خامس عشر : لا يجوز تعديل القيد أو الكشط أو النحشير فيه أو التغيير وعند اثبات بيان بطريق الخطأ يتم اثبات ابيان الصحيح بجواره مع وضع أقواس على البيان الخطا وفى هذه الحالة يتعين اعتماد التعديل من رئيس النيابة العامة المختص .', 'flashsa-lawyers');
INSERT INTO law_articles (law_name, article_number, article_text, source_url) VALUES ('قوانين الأحوال الشخصية', 'المادة 3', 'ينشر هذا القرار فى الوقائع المصرية ويعمل به اعتبارا من اليوم التالى لتاريخ نشره صدر فى 6/3/ 2000 
 
 وزير العدل 
 المستشار / فاروق سيف النصر', 'flashsa-lawyers');
